create or replace function public.world_fish_ground_list(p_uid uuid, p_region text) returns jsonb
language sql stable security definer set search_path to 'pg_catalog', 'public' as $$
  select coalesce(jsonb_agg(jsonb_build_object('habitat', g.habitat, 'ground_name', g.ground_name, 'description', g.description,
      'species_total', (select count(*) from public.world_fish_species s where s.habitat = g.habitat and s.active and (s.grounds is null or p_region = any (s.grounds))),
      'species_caught', (select count(*) from public.world_fish_log l join public.world_fish_species s using (fish_id) where l.owner_id = p_uid and s.habitat = g.habitat and (s.grounds is null or p_region = any (s.grounds))),
      'named', (select coalesce(jsonb_agg(jsonb_build_object('fish_id', n.fish_id, 'caught', exists (select 1 from public.world_fish_log l where l.owner_id = p_uid and l.fish_id = n.fish_id),
          'name', case when exists (select 1 from public.world_fish_log l where l.owner_id = p_uid and l.fish_id = n.fish_id) then n.fish_name end,
          'hint', n.description) order by n.sort), '[]'::jsonb)
        from public.world_fish_species n where n.named and n.active and n.habitat = g.habitat and (n.grounds is null or p_region = any (n.grounds))),
      'baits', (select coalesce(jsonb_agg(jsonb_build_object('fish_id', b.fish_id, 'name', b.fish_name, 'n', (c.inventory ->> b.fish_id)::int) order by b.sort), '[]'::jsonb)
        from public.world_fish_species b, public.world_characters c
       where c.owner_id = p_uid and coalesce((c.inventory ->> b.fish_id)::int, 0) > 0
         and exists (select 1 from public.world_fish_species n where n.named and n.active and n.fish_id = any (b.bait_for) and n.habitat = g.habitat
                       and (n.grounds is null or p_region = any (n.grounds)))))
    order by g.habitat), '[]'::jsonb)
  from public.world_fish_grounds g where g.region_id = p_region
$$;
revoke all on function public.world_fish_ground_list(uuid, text) from public, anon, authenticated;
do $d$
declare o text := pg_get_userbyid((select proowner from pg_proc where oid = 'public.world_fish_spot()'::regprocedure));
begin
  if o like 'fn_owner%' then execute format('grant execute on function public.world_fish_ground_list(uuid, text) to %I', o); end if;
end $d$;

create or replace function public.world_fish_at(p_habitat text default null, p_bait text default null) returns jsonb
language plpgsql security invoker set search_path to 'pg_catalog', 'public' as $$
begin
  perform set_config('yh.fish_habitat', coalesce(p_habitat, ''), true);
  perform set_config('yh.fish_bait', coalesce(p_bait, ''), true);
  return public.world_fish();
end $$;
revoke all on function public.world_fish_at(text, text) from public, anon;
grant execute on function public.world_fish_at(text, text) to authenticated;

insert into public.world_map_regions(region_id, territory_id, territory_name, region_name, region_type, danger_level, min_level, description, travel_from, gather_nodes, faction_control, is_starting_area, active, world_x, world_y, elevation, terrain_cost, rest_spot_type, rest_spot_name, rest_quality, rest_fee, rest_risk, is_safe_zone, shop_id, shop_name, has_stable, contested)
select x.region_id, x.territory_id, x.territory_name, x.region_name, x.region_type, x.danger_level, x.min_level, x.description, array(select jsonb_array_elements_text(x.travel_from)), '{}'::text[], x.faction_control, false, true, x.world_x, x.world_y, x.elevation, x.terrain_cost, x.rest_spot_type, x.rest_spot_name, x.rest_quality, x.rest_fee, x.rest_risk, x.is_safe_zone, x.shop_id, x.shop_name, false, false from jsonb_to_recordset($J$[{"region_id":"mukchang_ferry","territory_id":"mukjeok","territory_name":"묵적록","region_name":"묵창 나루","region_type":"village","danger_level":9,"min_level":40,"description":"먹빛 강을 건너는 나룻배가 닿는 작은 나루. 문패마다 글자가 반쯤 지워져 있고, 사람들은 서로를 사는 자리로 부른다.","travel_from":["frost_valley","blank_field"],"faction_control":"무주 금역","world_x":310,"world_y":128,"elevation":0,"terrain_cost":0.8,"rest_spot_type":"inn","rest_spot_name":"묵창 주막 객방","rest_quality":2,"rest_fee":160,"rest_risk":0,"is_safe_zone":true,"shop_id":"mukchang_shop","shop_name":"묵창 주막","theme":"water"},{"region_id":"blank_field","territory_id":"mukjeok","territory_name":"묵적록","region_name":"빈칸 벌판","region_type":"wilderness","danger_level":10,"min_level":41,"description":"이름이 거둬지고 정리되지 못한 먹귀들이 모여드는 벌판. 풀잎마다 지워진 글자의 얼룩이 묻어 있다.","travel_from":["mukchang_ferry","meokbi_forest"],"faction_control":"무주 금역","world_x":222,"world_y":168,"elevation":0,"terrain_cost":1,"rest_spot_type":"field_camp","rest_spot_name":"임시 야영지","rest_quality":1,"rest_fee":2,"rest_risk":30,"is_safe_zone":false,"shop_id":null,"shop_name":null,"theme":"wild"},{"region_id":"meokbi_forest","territory_id":"mukjeok","territory_name":"묵적록","region_name":"먹비 숲","region_type":"forest","danger_level":10,"min_level":42,"description":"먹물 같은 비가 그치지 않는 숲. 잎에 맺힌 빗방울을 손등에 받으면 남의 꿈이 비친다.","travel_from":["blank_field","myeongbu_tower"],"faction_control":"무주 금역","world_x":148,"world_y":222,"elevation":1,"terrain_cost":1,"rest_spot_type":"field_camp","rest_spot_name":"임시 야영지","rest_quality":1,"rest_fee":2,"rest_risk":30,"is_safe_zone":false,"shop_id":null,"shop_name":null,"theme":"wild"},{"region_id":"myeongbu_tower","territory_id":"mukjeok","territory_name":"묵적록","region_name":"명부 탑","region_type":"archive","danger_level":10,"min_level":44,"description":"정청이 거둔 이름의 원부를 쌓아 두던 옛 탑. 층마다 죽간이 무너져 내려 먹귀가 모여 산다.","travel_from":["meokbi_forest","nine_court"],"faction_control":"무주 금역","world_x":118,"world_y":122,"elevation":3,"terrain_cost":1,"rest_spot_type":"field_camp","rest_spot_name":"임시 야영지","rest_quality":1,"rest_fee":2,"rest_risk":30,"is_safe_zone":false,"shop_id":null,"shop_name":null,"theme":"shrine"},{"region_id":"nine_court","territory_id":"mukjeok","territory_name":"묵적록","region_name":"아홉 칸 뜰","region_type":"haunted_garden","danger_level":10,"min_level":45,"description":"명부 탑 아래, 바닥에 아홉 칸 진이 그려진 뜰. 가운데 칸의 먹은 아직 마르지 않았다.","travel_from":["myeongbu_tower"],"faction_control":"무주 금역","world_x":52,"world_y":172,"elevation":0,"terrain_cost":1,"rest_spot_type":"field_camp","rest_spot_name":"임시 야영지","rest_quality":1,"rest_fee":2,"rest_risk":30,"is_safe_zone":false,"shop_id":null,"shop_name":null,"theme":"shrine"}]$J$::jsonb) as x(region_id text, territory_id text, territory_name text, region_name text, region_type text, danger_level int, min_level int, description text, travel_from jsonb, gather_nodes jsonb, faction_control text, is_starting_area boolean, active boolean, world_x int, world_y int, elevation int, terrain_cost numeric, rest_spot_type text, rest_spot_name text, rest_quality int, rest_fee int, rest_risk int, is_safe_zone boolean, shop_id text, shop_name text, has_stable boolean, contested boolean)
on conflict (region_id) do update set travel_from = excluded.travel_from, description = excluded.description, min_level = excluded.min_level, danger_level = excluded.danger_level, world_x = excluded.world_x, world_y = excluded.world_y, rest_fee = excluded.rest_fee, shop_id = excluded.shop_id, shop_name = excluded.shop_name, active = excluded.active, territory_id = excluded.territory_id, territory_name = excluded.territory_name;
insert into public.world_region_theme(region_id, theme)
select x.region_id, x.theme from jsonb_to_recordset($J$[{"region_id":"mukchang_ferry","theme":"water"},{"region_id":"blank_field","theme":"wild"},{"region_id":"meokbi_forest","theme":"wild"},{"region_id":"myeongbu_tower","theme":"shrine"},{"region_id":"nine_court","theme":"shrine"}]$J$::jsonb) as x(region_id text, theme text)
on conflict (region_id) do update set theme = excluded.theme;
update public.world_map_regions set travel_from = array_append(travel_from, 'mukchang_ferry') where region_id = 'frost_valley' and not ('mukchang_ferry' = any (travel_from));
insert into public.world_weather_climate(territory_id, weights) values ('mukjeok', $J${"drizzle":20,"cloudy":18,"rain":16,"fog":18,"clear":14,"wind":14}$J$::jsonb) on conflict (territory_id) do update set weights = excluded.weights;
insert into public.world_region_profiles(region_id, biome_key, biome_name, faction_style, signature_clue, signature_event, signature_items, survival_hazard, visual_identity, signature_resources, investigation_reward)
select x.region_id, x.biome_key, x.biome_name, x.faction_style, x.signature_clue, x.signature_event, array(select jsonb_array_elements_text(x.signature_items)), x.survival_hazard, x.visual_identity, array(select jsonb_array_elements_text(x.signature_resources)), x.investigation_reward from jsonb_to_recordset($J$[{"region_id":"mukchang_ferry","biome_key":"water","biome_name":"물가·나루","faction_style":"나루 사람들·정청 서리","signature_clue":"묵창 나루의 문패: 글자가 반쯤 지워져 사는 자리로만 서로를 부른다.","signature_event":"묵창 나루 고유 사건: 주민 명부에서 이름이 하나둘 흐려진다.","signature_items":["mukchang_ink","river_reed","tonic"],"survival_hazard":"이름 흐림·비싼 물자","visual_identity":"먹빛 강, 반쯤 지워진 문패, 주막 등불","signature_resources":["herb","mukchang_ink","river_reed","tonic","travel_ration"],"investigation_reward":"먹으로 지운 이름의 기록"},{"region_id":"blank_field","biome_key":"wild","biome_name":"들판·초원","faction_style":"먹귀와 흑련회 거둠꾼","signature_clue":"빈칸 벌판의 문패 무더기: 뜯긴 문패마다 지운 이름의 획이 남았다.","signature_event":"빈칸 벌판 고유 사건: 먹귀를 풀어 보내면 그 기억이 손등에 먹으로 남는다.","signature_items":["moon_moss","medicine_base","herb"],"survival_hazard":"이름 흐림·매복·독","visual_identity":"흰 억새, 먹 얼룩, 이름 걸린 허수아비","signature_resources":["blank_hanji","erased_plate","herb","inkstone","medicine_base","moon_moss","mukchang_ink","river_reed","seal_paper","travel_ration"],"investigation_reward":"먹으로 지운 이름의 기록"},{"region_id":"meokbi_forest","biome_key":"wild","biome_name":"숲·먹비","faction_style":"꿈을 무는 요괴들","signature_clue":"먹비 숲의 숙소 벽: 옛 조사원이 쓴 이름이 먹비에 번져 읽히지 않는다.","signature_event":"먹비 숲 고유 사건: 빗방울을 받으면 남의 꿈이 비친다.","signature_items":["tonic","travel_ration","herb"],"survival_hazard":"이름 흐림·환영·물살","visual_identity":"그치지 않는 먹비, 흑단 고목, 꿈 비치는 웅덩이","signature_resources":["ghost_ash","herb","medicine_base","meokbi_ebony","meokbi_moss","resin","spirit_dust","tonic","travel_ration","wood"],"investigation_reward":"먹으로 지운 이름의 기록"},{"region_id":"myeongbu_tower","biome_key":"shrine","biome_name":"탑·서고","faction_style":"서리의 넋과 엉킨 먹귀","signature_clue":"명부 탑의 원부: 거둔 이름의 작성자 칸만 먹이 번져 있다.","signature_event":"명부 탑 고유 사건: 꼭대기에 먹귀가 엉켜 한 덩어리가 되었다.","signature_items":["blank_hanji","travel_ration","herb"],"survival_hazard":"이름 흐림·결계·거울","visual_identity":"쏟아진 죽간, 나선 계단, 바람 드는 누각","signature_resources":["blank_hanji","erased_plate","ghost_ash","herb","inkstone","ore","raw_iron","register_slip","seal_paper","spirit_dust","travel_ration"],"investigation_reward":"먹으로 지운 이름의 기록"},{"region_id":"nine_court","biome_key":"shrine","biome_name":"뜰·진법","faction_style":"진에 묶인 먹귀","signature_clue":"아홉 칸 뜰의 진: 가운데 칸의 먹이 아직 마르지 않았다.","signature_event":"아홉 칸 뜰 고유 사건: 아홉째 칸에 묶인 먹귀가 커다랗게 부풀었다.","signature_items":["meokbi_moss","mukchang_ink","river_reed"],"survival_hazard":"이름 흐림·봉인·우물","visual_identity":"아홉 칸 진, 주춧돌 줄, 끝 모를 우물","signature_resources":["erased_plate","meokbi_moss","mukchang_ink","ore","raw_iron","register_slip","river_reed","seal_paper","spirit_core","spirit_dust"],"investigation_reward":"먹으로 지운 이름의 기록"}]$J$::jsonb) as x(region_id text, biome_key text, biome_name text, faction_style text, signature_clue text, signature_event text, signature_items jsonb, survival_hazard text, visual_identity text, signature_resources jsonb, investigation_reward text)
on conflict (region_id) do update set biome_name = excluded.biome_name, faction_style = excluded.faction_style, signature_clue = excluded.signature_clue, signature_event = excluded.signature_event, signature_items = excluded.signature_items, survival_hazard = excluded.survival_hazard, visual_identity = excluded.visual_identity, signature_resources = excluded.signature_resources;
insert into public.world_region_lore(region_id, lines)
select x.region_id, x.lines from jsonb_to_recordset($J$[{"region_id":"mukchang_ferry","lines":[{"s":null,"t":"먹빛 강을 건너는 나룻배가 닿는 작은 나루입니다. 문패마다 글자가 반쯤 지워져 있고, 물가에 매인 배의 이름도 읽을 수 없습니다."},{"s":null,"t":"나루 사람들은 서로를 이름 대신 사는 자리로 부릅니다. 주막 한 채가 가게와 숙소를 겸하고, 그 구석 등불 아래에서 정청 서리가 명부를 대조하고 있습니다."}]},{"region_id":"blank_field","lines":[{"s":null,"t":"빈칸 벌판입니다. 흰 억새가 끝없이 이어지고, 풀잎마다 지워진 글자의 얼룩이 묻어 있습니다."},{"s":null,"t":"이름이 거둬진 뒤 갈 곳을 잃은 먹귀들이 이곳으로 모여듭니다. 바람이 멎으면 누군가 「기억해 줘」라고 속삭이는 소리가 들립니다."}]},{"region_id":"meokbi_forest","lines":[{"s":null,"t":"먹비 숲입니다. 먹물 같은 비가 그치지 않습니다. 잎에 맺힌 빗방울을 손등에 받으면 남의 꿈이 비칩니다."},{"s":null,"t":"숲 안쪽 어딘가에 옛 정청 조사원이 머물던 숙소가 있다고 합니다. 그가 누구였는지는 아무도 기억하지 못합니다."}]},{"region_id":"myeongbu_tower","lines":[{"s":null,"t":"명부 탑입니다. 정청이 거둔 이름의 원부를 쌓아 두던 옛 탑입니다. 층마다 죽간이 무너져 내려 계단을 덮었습니다."},{"s":null,"t":"원부의 작성자 칸만 하나같이 먹이 번져 있습니다. 탑 꼭대기에서는 엉킨 먹귀들이 서로를 부르는 소리가 내려옵니다."}]},{"region_id":"nine_court","lines":[{"s":null,"t":"아홉 칸 뜰입니다. 명부 탑 아래 바닥에 아홉 칸 진이 그려져 있습니다. 가운데 칸의 먹은 아직 마르지 않았습니다."},{"s":null,"t":"칸을 하나 밟을 때마다 누군가의 기억이 발밑에서 올라옵니다. 뜰 끝의 우물은 바닥이 보이지 않습니다."}]}]$J$::jsonb) as x(region_id text, lines jsonb)
on conflict (region_id) do update set lines = excluded.lines;
insert into public.world_exploration_nodes(node_id, region_id, parent_node_id, hierarchy_level, node_name, description, min_level, sort_order)
