on conflict (item_id, mechanic_key) do nothing;
update public.world_item_catalog i set reference_price = greatest(
    ceil(1.2 * (select min(t.v) from (select sum(m.reference_price * (x.value)::int * 1.0 / greatest(1, cr.output_qty)) v from public.world_crafting_recipes cr, jsonb_each_text(cr.ingredients) x
      join public.world_item_catalog m on m.item_id = x.key where cr.output_item = i.item_id group by cr.recipe_id) t)),
    coalesce(ceil(1.15 * (select max(f.reference_price) from public.world_item_catalog f where f.tier = 6 and f.category = i.category and f.base_item_id is null
      and f.item_id not like 'raid%' and coalesce((f.equipment_traits ->> 'life_slot'), '') = coalesce((i.equipment_traits ->> 'life_slot'), ''))), 0))
 where i.item_id in (select jsonb_array_elements_text($J$["w_melee7_base","w_melee7_heavy","w_melee7_keen","w_melee7_silent","w_ranged7_base","w_ranged7_heavy","w_ranged7_keen","w_ranged7_silent","w_magic7_base","w_magic7_heavy","w_magic7_keen","w_magic7_silent","a7_iron","a7_light","a7_robe","a7_shade","h7_calm","h7_guard","h7_wise","s7_road","s7_sturdy","s7_swift","n7_keen","n7_luck","n7_plenty","m7_purify","m7_spell","m7_ward","k7_awe","k7_ghost","k7_hide","lt_knife_8","lt_pick_7","lt_sickle_7","lt_lantern_7","lt_compass_7","lt_rod_7","lt_rod_7b","lt_hammer_7","lt_needle_7","lt_carve_7","lt_still_7","lt_cook_7"]$J$::jsonb));
update public.world_item_catalog i set reference_price = greatest(i.reference_price,
    ceil(1.1 * (select min(t.v) from (select sum(m.reference_price * (x.value)::int * 1.0 / greatest(1, cr.output_qty)) v from public.world_crafting_recipes cr, jsonb_each_text(cr.ingredients) x
      join public.world_item_catalog m on m.item_id = x.key where cr.output_item = i.item_id group by cr.recipe_id) t)))
 where i.item_id in (select jsonb_array_elements_text($J$["goby_braise","carp_glue","inkline_eel_grill","dark_eye_drops","bronze_scale_plate","shad_oil","shad_lamp","angler_gall_pill","crucian_reed_porridge","bitterling_ink","mist_crucian_steam","name_carving_soup","blank_fill_pill","salmon_ink_grill","rainproof_oil","register_eel_grill","dragon_eye_essence","tuna_ink_feast","name_ink_charm","meokgwi_incense","meokbi_umbrella","hf_wall_doorplate","hf_wall_bamboo_blind","hf_rug_ink_pond","hf_window_meokbi","hf_shelf_register","hf_rubbing_doorplate_carp","hf_rubbing_blank_snakehead","hf_rubbing_blind_dragon","hf_rubbing_inkscale_tuna","hf_rubbing_meokbi_salmon","hf_rubbing_bamboo_eel","hf_tank_bamboo_eel"]$J$::jsonb))
   and exists (select 1 from public.world_crafting_recipes cr where cr.output_item = i.item_id);
insert into public.world_item_catalog(item_id, item_name, category, tier, description, stackable, required_stats, required_job, required_faction, minimum_level,
  rarity, acquisition_difficulty, drop_rate_modifier, equipment_traits, crafting_specialization, tradeable, reference_price, stack_size, base_item_id, quality_grade, use_fx)
select i.item_id || '_hq', i.item_name || ' (우수)', i.category, i.tier, i.description || ' ' || public.world_item_hq_note(i.item_id, i.category), i.stackable,
  i.required_stats, i.required_job, i.required_faction, i.minimum_level, i.rarity, i.acquisition_difficulty, i.drop_rate_modifier,
  case when i.category in ('weapon', 'armor', 'hat', 'shoes', 'norigae', 'amulet', 'mask', 'tool') then public.world_item_hq_traits(i.equipment_traits) else i.equipment_traits end,
  i.crafting_specialization, i.tradeable, ceil(coalesce(i.reference_price, 0) * 1.3), i.stack_size, i.item_id, 1, null
  from public.world_item_catalog i
 where i.item_id in (select jsonb_array_elements_text($J$["name_ink_charm","meokgwi_incense","meokbi_umbrella","goby_braise","inkline_eel_grill","dark_eye_drops","shad_lamp","angler_gall_pill","crucian_reed_porridge","mist_crucian_steam","name_carving_soup","blank_fill_pill","salmon_ink_grill","register_eel_grill","dragon_eye_essence","tuna_ink_feast","lt_knife_8","lt_pick_7","lt_sickle_7","lt_lantern_7","lt_compass_7","lt_rod_7","lt_rod_7b","lt_hammer_7","lt_needle_7","lt_carve_7","lt_still_7","lt_cook_7","w_melee7_base","w_melee7_heavy","w_melee7_keen","w_melee7_silent","w_ranged7_base","w_ranged7_heavy","w_ranged7_keen","w_ranged7_silent","w_magic7_base","w_magic7_heavy","w_magic7_keen","w_magic7_silent","a7_iron","a7_light","a7_robe","a7_shade","h7_calm","h7_guard","h7_wise","s7_road","s7_sturdy","s7_swift","n7_keen","n7_luck","n7_plenty","m7_purify","m7_spell","m7_ward","k7_awe","k7_ghost","k7_hide"]$J$::jsonb))
on conflict (item_id) do nothing;
insert into public.world_fish_species(fish_id, fish_name, habitat, rarity, min_level, phase, weather, size_min, size_max, description, sort, active, grounds, bait_for, named)
select x.fish_id, x.fish_name, x.habitat, x.rarity, x.min_level, x.phase, x.weather, x.size_min, x.size_max, x.description,
       (select coalesce(max(sort), 0) from public.world_fish_species) + x.n, true, case when x.ground is null then null else array[x.ground] end, '{}'::text[], x.named
  from jsonb_to_recordset($J$[{"fish_id":"stone_goby","fish_name":"돌틈 망둥이","habitat":"canal","rarity":"common","phase":null,"weather":null,"min_level":20,"size_min":8,"size_max":18,"description":"수로 돌틈에 붙어 사는 망둥이. 손으로 집어도 잘 놀라지 않는다.","ground":null,"named":false,"n":1},{"fish_id":"sluice_carp","fish_name":"수문 잉어","habitat":"canal","rarity":"uncommon","phase":null,"weather":null,"min_level":24,"size_min":30,"size_max":70,"description":"수문 아래 거슬러 오르는 잉어. 비늘이 두껍고 질기다.","ground":null,"named":false,"n":2},{"fish_id":"inkline_eel","fish_name":"먹줄 장어","habitat":"canal","rarity":"rare","phase":"night","weather":null,"min_level":28,"size_min":50,"size_max":110,"description":"등에 먹줄을 그은 듯한 장어. 삼경에만 굴에서 나온다.","ground":null,"named":false,"n":3},{"fish_id":"well_blindfish","fish_name":"우물 장님고기","habitat":"deep","rarity":"uncommon","phase":null,"weather":null,"min_level":24,"size_min":10,"size_max":25,"description":"깊은 우물에 사는 눈 없는 물고기. 몸이 반쯤 비친다.","ground":null,"named":false,"n":4},{"fish_id":"bronze_catfish","fish_name":"청동 메기","habitat":"deep","rarity":"rare","phase":"dusk","weather":null,"min_level":28,"size_min":60,"size_max":140,"description":"비늘이 청동처럼 굳은 메기. 땅거미가 지면 바닥에서 올라온다.","ground":null,"named":false,"n":5},{"fish_id":"ash_lanternfish","fish_name":"잿빛 샛비늘치","habitat":"abyss","rarity":"uncommon","phase":null,"weather":null,"min_level":24,"size_min":8,"size_max":20,"description":"심연에서 잿빛으로 빛나는 작은 물고기. 기름이 많다.","ground":null,"named":false,"n":6},{"fish_id":"nameless_angler","fish_name":"이름 없는 아귀","habitat":"abyss","rarity":"rare","phase":null,"weather":"fog","min_level":28,"size_min":40,"size_max":100,"description":"안개 낀 날 심연에서 올라오는 아귀. 등불 대신 지운 글자를 매달았다.","ground":null,"named":false,"n":7},{"fish_id":"reed_crucian","fish_name":"갈대 버들붕어","habitat":"marsh","rarity":"common","phase":null,"weather":null,"min_level":20,"size_min":8,"size_max":20,"description":"갈대 뿌리 사이에 숨어 사는 붕어. 버들잎처럼 납작하다.","ground":null,"named":false,"n":8},{"fish_id":"inkdot_bitterling","fish_name":"먹점 납자루","habitat":"marsh","rarity":"uncommon","phase":null,"weather":null,"min_level":24,"size_min":6,"size_max":14,"description":"몸에 먹점이 찍힌 납자루. 잡으면 먹물을 뱉는다.","ground":null,"named":false,"n":9},{"fish_id":"mist_bitterling","fish_name":"물안개 각시붕어","habitat":"lake","rarity":"uncommon","phase":null,"weather":"fog","min_level":24,"size_min":6,"size_max":15,"description":"물안개 낀 날 수면 가까이 떠오르는 각시붕어.","ground":null,"named":false,"n":10},{"fish_id":"doorplate_carp","fish_name":"문패 잉어","habitat":"river","rarity":"legendary","phase":"dusk","weather":"drizzle","min_level":40,"size_min":60,"size_max":140,"description":"비늘에 지워진 문패의 글자가 새겨진 잉어. 땅거미 가랑비에 강물고기 냄새를 따라 올라온다더라.","ground":"mukchang_ferry","named":true,"n":11},{"fish_id":"blank_snakehead","fish_name":"빈칸 가물치","habitat":"marsh","rarity":"legendary","phase":"night","weather":"cloudy","min_level":40,"size_min":70,"size_max":160,"description":"몸 한가운데가 빈칸처럼 하얀 가물치. 구름 낀 삼경에 늪물고기 냄새를 좋아한다더라.","ground":"blank_field","named":true,"n":12},{"fish_id":"meokbi_salmon","fish_name":"먹비 대산천어","habitat":"lake","rarity":"legendary","phase":"dawn","weather":"rain","min_level":40,"size_min":50,"size_max":110,"description":"먹비가 쏟아지는 해돋이에 못물고기 냄새를 맡고 떠오른다는 커다란 산천어.","ground":"meokbi_forest","named":true,"n":13},{"fish_id":"blind_dragon","fish_name":"눈먼 용","habitat":"deep","rarity":"legendary","phase":"noon","weather":"clear","min_level":40,"size_min":120,"size_max":260,"description":"우물 바닥에 산다는 눈먼 용. 맑은 한낮, 깊은 물고기 냄새가 내려가면 올라온다더라.","ground":"nine_court","named":true,"n":14},{"fish_id":"bamboo_eel","fish_name":"죽간 대장어","habitat":"canal","rarity":"legendary","phase":"night","weather":"fog","min_level":40,"size_min":90,"size_max":200,"description":"죽간을 엮은 듯 마디진 장어. 안개 낀 삼경, 수로 물고기 냄새를 따라 나온다더라.","ground":"myeongbu_tower","named":true,"n":15},{"fish_id":"inkscale_tuna","fish_name":"먹비늘 다랑어","habitat":"sea","rarity":"legendary","phase":"dawn","weather":"wind","min_level":40,"size_min":120,"size_max":240,"description":"먹물 비늘을 두른 다랑어. 삭풍 부는 해돋이에 바닷물고기 냄새를 좇아 앞바다로 든다더라.","ground":"mukchang_ferry","named":true,"n":16}]$J$::jsonb)
    as x(fish_id text, fish_name text, habitat text, rarity text, min_level int, phase text, weather text, size_min numeric, size_max numeric, description text, ground text, named boolean, n int)
