select x.k, x.kind, x.tier, x.name, x.cond, '묵적록', x.rule, false, x.sort
  from jsonb_to_recordset($J$[{"k":"fr_mukjeok","kind":"frame","tier":"legend","name":"먹비 테","cond":"묵적록 다섯 곳에 모두 닿으면","rule":{"title":"mk_walker"},"sort":1500},{"k":"sl_muk","kind":"seal","tier":"legend","name":"낙관 「墨」","cond":"명어 여섯을 모두 낚으면","rule":{"title":"mk_named_all"},"sort":1501}]$J$::jsonb) as x(k text, kind text, tier text, name text, cond text, rule jsonb, sort int)
on conflict (cosmetic_key) do update set cosmetic_name = excluded.cosmetic_name, condition_text = excluded.condition_text, rule = excluded.rule, tier = excluded.tier, category = excluded.category;
select pg_temp.yh_patch('public.world_name_styles()', '(1016, ''cat'', ''레거시'', 1))', '(1016, ''cat'', ''레거시'', 1), (1031, ''cat'', ''묵적록'', 6))');
insert into public.world_gathering_discoveries(owner_id, spot_id)
select c.owner_id, gs.spot_id from public.world_characters c
  cross join public.world_gathering_spots gs join public.world_exploration_nodes n on n.node_id = gs.node_id and n.hierarchy_level = 1 and n.region_id in ('mukchang_ferry', 'blank_field', 'meokbi_forest', 'myeongbu_tower', 'nine_court')
on conflict do nothing;
create or replace function pg_temp.yh_patch(p_fn text, p_old text, p_new text, p_n int default 1) returns void
language plpgsql as $$
declare d text; o text; k int;
begin
  d := pg_get_functiondef(p_fn::regprocedure);
  k := (length(d) - length(replace(d, p_old, ''))) / greatest(1, length(p_old));
  if k = 0 and position(p_new in d) > 0 then return; end if;
  if k <> p_n then raise exception '고칠 자리 수가 다름: % (%번 기대, %번)', p_fn, p_n, k; end if;
  o := pg_get_userbyid((select proowner from pg_proc where oid = p_fn::regprocedure));
  if o like 'fn_owner%' and not pg_has_role('postgres', o, 'usage') then execute format('grant %I to postgres with inherit true, set true', o); end if;
  execute replace(d, p_old, p_new);
end $$;
select pg_temp.yh_patch('public.world_faction_task_count(uuid,jsonb,timestamp with time zone)', 'when ''craft'' then ''craft'' end', 'when ''craft'' then ''craft'' when ''rest'' then ''rest'' end');
select pg_temp.yh_patch('public.world_faction_task_label(jsonb)', 'when ''craft'' then ''제작'' else', 'when ''craft'' then ''제작'' when ''rest'' then ''쉬기'' else');
insert into public.world_quest_npcs(npc_key, npc_name, bio)
select x.npc_key, x.npc_name, x.bio from jsonb_to_recordset($J$[{"npc_key":"q:mk_hisu","npc_name":"정청 서리 희수","bio":"정청 출납 서리. 묵창 나루 주민 명부의 대조를 맡았다. 평생 틀리지 않으려고 쓴 손을 가졌다."},{"npc_key":"q:mk_daon","npc_name":"다온","bio":"묵창 나루의 열 살 남짓한 아이. 부모 없이 문패가 다 지워진 집에 산다. 공책에 이름을 적어 두면 안 잊는다고 믿는다."},{"npc_key":"q:mk_wolha","npc_name":"월하","bio":"흑련회 이름 거둠꾼. 「월하」는 부르는 이름이고 본명은 흑련회 회원 장부에 맡겨 두었다."},{"npc_key":"q:mk_shadow","npc_name":"먹그림자","bio":"먹으로 그린 사람의 윤곽. 주인공과 같은 말투로 제 이야기를 한다."},{"npc_key":"q:mk_meok","npc_name":"먹귀","bio":"이름을 잃은 동안 주인공 자리에 붙는 이름표."},{"npc_key":"q:mk_seoyul","npc_name":"서율","bio":"옛 정청 조사원. 서하의 오라버니. 기억 조각 속의 목소리."},{"npc_key":"q:mk_seoha","npc_name":"서하","bio":"기억 조각 속의 아이."}]$J$::jsonb) as x(npc_key text, npc_name text, bio text)
on conflict (npc_key) do update set npc_name = excluded.npc_name, bio = excluded.bio;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, sort, epilogue, active)
select x.quest_id, 'side', x.cat, x.title, x.summary, x.region_id, x.min_level, array(select jsonb_array_elements_text(x.after)), x.sort, x.epilogue, true from jsonb_to_recordset($J$[{"quest_id":"mkq_1","cat":"외전·묵적록","title":"먹 거둔 땅","summary":"묵창 나루의 주민 명부에서 이름이 하나둘 흐려진다. 정청 서리 희수와 함께 먹빛 강가의 나루로 간다.","region_id":"mukchang_ferry","min_level":40,"after":["gq_5"],"sort":1300,"epilogue":[]},{"quest_id":"mkq_2","cat":"외전·묵적록","title":"빈칸 벌판","summary":"정청이 먹귀를 가둬 두던 빈칸 벌판의 테가 터졌다. 이름을 들을 수 있는 사람은 나 하나다.","region_id":"blank_field","min_level":41,"after":["mkq_1"],"sort":1301,"epilogue":[]},{"quest_id":"mkq_3","cat":"외전·묵적록","title":"먹비 숲","summary":"남의 꿈을 꾸고, 팔에 먹 무늬가 번진다. 먹비 숲에서 옛 조사원 서율의 흔적을 찾는다.","region_id":"mukchang_ferry","min_level":42,"after":["mkq_2"],"sort":1302,"epilogue":[]},{"quest_id":"mkq_4","cat":"외전·묵적록","title":"명부 탑","summary":"나루에 엉킴이 번진다. 정청은 다온의 이름을 거두기로 한다. 마을 먹귀가 모인 명부 탑으로 오른다.","region_id":"mukchang_ferry","min_level":44,"after":["mkq_3"],"sort":1303,"epilogue":[]},{"quest_id":"mkq_5","cat":"외전·묵적록","title":"아홉 칸 뜰","summary":"매듭 안쪽, 아홉 칸 명부. 먹그림자와 마주하고 돌아오는 이름을 듣는다.","region_id":"nine_court","min_level":45,"after":["mkq_4"],"sort":1304,"epilogue":[]}]$J$::jsonb) as x(quest_id text, kind text, cat text, title text, summary text, region_id text, min_level int, after jsonb, sort int, epilogue jsonb, active boolean)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, epilogue = excluded.epilogue, active = excluded.active;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward)
select x.quest_id, x.step, x.title, x.goal, x.need, x.lines, x.reward from jsonb_to_recordset($J$[{"quest_id":"mkq_1","step":1,"title":"나루의 서리","goal":"정청 대청에서 출납 서리 희수를 만난다","need":{"at":["hq_yard"]},"lines":[{"s":null,"t":"정청 대청은 비가 오기 전처럼 눅눅했다. 대청 마루에 설 때마다 그날이 떠올랐다. 이름도 없이 정청 문 앞에 쓰러져 있던 날. 내 이름을 처음 장부에 올려 준 사람은 사건 서기관 연서희였다."},{"s":null,"t":"그 연서희의 서안 옆에서, 출납 서리 하나가 장부를 끌어안고 일어섰다. 단정하게 틀어 올린 머리, 먹물이 손톱 밑까지 밴 가는 손가락."},{"s":"q:mk_hisu","t":"조사원이시죠. 출납 서리 희수입니다. 이번 묵창 나루 건, 제가 명부 대조를 맡았습니다."},{"s":null,"t":"인사는 그것으로 끝이었다. 희수는 곧장 장부를 펼쳐 손가락으로 한 줄을 짚었다. 이름이 있어야 할 자리에 젖은 종이 같은 얼룩만 남아 있었다."},{"s":"q:mk_hisu","t":"나루 주민 명부에서 이름이 흐려지는 사람이 석 달 사이 열하나입니다. 먹이 번진 게 아니라, 글자가 스스로 옅어지고 있어요."},{"s":"q:mk_hisu","t":"정청은 이런 땅을 「먹 거둔 땅」이라고 적습니다. 이름을 거둔 자리에 먹이 남는다는 뜻이에요."},{"s":null,"t":"희수는 장부를 덮고, 그 위에 손을 얹은 채 잠깐 나를 보았다. 무언가를 확인하는 눈이었다."},{"s":"q:mk_hisu","t":"길은 제가 압니다. 묵창 나루까지 함께 가 주세요."}],"reward":{}},{"quest_id":"mkq_1","step":2,"title":"먹귀","goal":"묵창 나루로 간다","need":{"at":["mukchang_ferry"]},"lines":[{"s":null,"t":"나루는 조용했다. 문패마다 글자가 반쯤 지워져 있었고, 물가에 매인 배의 이름도 읽을 수 없었다."},{"s":null,"t":"나루 끝 강둑에 아이 하나가 쓰러져 있었다. 그 위로 검은 형체가 엎드려 있었다. 사람의 어깨 같기도, 흘러내린 먹물 같기도 했다."},{"s":null,"t":"내가 한 걸음 내딛자, 희수가 팔을 뻗어 앞을 막았다."},{"s":"q:mk_hisu","t":"물러서세요, 조사원. 저건 {직업:호위=칼로 베어지는/암영=칼끝에 걸리는/월궁=화살에 꿰뚫리는/퇴마=부적으로 쫓겨나는/봉인=봉인으로 묶이는/의무=침이나 약으로 다스려지는} 게 아닙니다."},{"s":null,"t":"그때 들렸다. 귀가 아니라 가슴 안쪽 어딘가에서, 누군가 같은 말을 되풀이하고 있었다."},{"s":null,"t":"이름이었다. 끝 글자를 끝내 맺지 못하는 이름."},{"s":null,"t":"나는 희수의 팔을 지나, 그 이름을 끝까지 불렀다."},{"s":null,"t":"검은 형체가 멈췄다. 아주 잠깐, 웃는 얼굴 같은 것이 스쳤다가 바람에 흩어졌다. 손끝이 차가워졌다. 들여다보니 검지 끝에 먹 한 점이 묻어 있었다."},{"s":null,"t":"아이가 기침을 하며 눈을 떴다. 희수는 아이에게 달려가는 대신, 그 자리에 선 채 나를 보았다. 핏기가 가신 얼굴이었다."},{"s":"q:mk_hisu","t":"……방금, 그 이름을 들으셨습니까?"},{"s":null,"t":"희수는 대답을 기다리지 않았다. 품에서 낡은 장부를 꺼내 빠르게 넘기다가, 한 장에서 손을 멈췄다. 겉장에 내 이름이 적혀 있었다. 연서희의 글씨였다."},{"s":"q:mk_hisu","t":"정청 기록에는 조사원 같은 사람을 「빈 고리」라고 적어요. 이름을 한 번 잃었다가 다시 묶인 사람. 그 매듭 안쪽에, 이름 하나가 들어앉을 자리가 비어 있다고."},{"s":"q:mk_hisu","t":"정청 문 앞에서 발견되셨던 날, 연 서기관님이 이 장부에 조사원 이름을 처음 올렸지요. 그날부터 이 장부는 서고 한 칸에 따로 꽂혀 있었습니다. 정청은 처음부터 알고 있었어요."},{"s":null,"t":"희수의 목소리는 사과하는 것도 변명하는 것도 아니었다. 그저 적힌 것을 읽는 목소리였다. 장부를 덮는 손끝만 아주 조금 떨렸다."},{"s":null,"t":"희수는 장부를 품에 다시 넣고, 그제야 아이 곁에 무릎을 꿇었다."},{"s":"q:mk_hisu","t":"아이는 제가 집에 데려다주겠습니다. 그동안 나루 바깥 강둑 쪽에 저런 것이 더 있는지 둘러봐 주세요. 강둑을 따라가면 빈칸 벌판 어귀가 나옵니다."}],"reward":{}},{"quest_id":"mkq_1","step":3,"title":"따라오는 아이","goal":"빈칸 벌판 어귀를 3번 탐색한 뒤 묵창 나루로 돌아온다","need":{"at":["mukchang_ferry"],"tasks":[{"t":"search","r":["blank_field"],"n":3}]},"lines":[{"s":null,"t":"강둑을 따라 벌판 어귀를 돌고 나루로 돌아오는 내내, 발소리 하나가 몇 걸음 뒤에서 따라왔다. 돌아보면 멈췄고, 걸으면 다시 따라왔다."},{"s":null,"t":"강둑에 쓰러져 있던 아이였다. 젖은 소매를 꼭 쥐고, 내 얼굴과 손끝을 번갈아 보았다."},{"s":"q:mk_daon","t":"……아까 그거, 뭐라고 했어요?"},{"s":"q:mk_daon","t":"다른 사람들은 그거 보면 도망가요. 근데 아까는 그게 말하는 걸 듣고 있었잖아요."},{"s":"q:mk_daon","t":"걔가 뭐라고 했어요? 왜 저한테 붙어 있었어요? 이름은 어떻게 알았어요?"},{"s":null,"t":"나는 대답하지 못했다. 아이는 대답을 못 들어도 물러서지 않았다."},{"s":null,"t":"골목 끝에서 희수가 걸어왔다. 아이를 집에 데려다주고 오는 길이었는지, 소매 끝이 젖어 있었다. 희수는 아이를 보자 걸음을 멈추고 이마를 짚었다."},{"s":"q:mk_hisu","t":"다온아. 집에 가 있으라고 했잖니."},{"s":"q:mk_daon","t":"조사원 님 마을 떠날 때까지만 있을래요."},{"s":"q:mk_hisu","t":"조사에 방해가 될 수 있어."},{"s":"q:mk_daon","t":"방해 안 해요. 진짜로요. 저기 저 기둥까지만 따라갈게요."},{"s":null,"t":"아이는 한발 물러섰다. 그리고 내가 걷기 시작하자 기둥을 지나 다시 따라왔다. 희수가 작게 한숨을 쉬었다. 꾸짖으려던 입을 다물고, 아이를 한동안 바라보다가 내 쪽으로 몸을 돌렸다."},{"s":"q:mk_hisu","t":"다온은 부모가 없어요. 마을 사람들이 오래 비어 있던 집에 들였죠. 나루 안쪽, 문패가 다 지워진 집이에요."},{"s":"q:mk_hisu","t":"먹귀가 저 아이한테만 유독 자주 붙습니다. 그 집이 걸려요. 오늘 밤은 주막에 묵으며 쉬어 주시겠습니까. 아이 집이 주막 바로 뒤예요."}],"reward":{"xp":6960}},{"quest_id":"mkq_1","step":4,"title":"삐뚤빼뚤한 이름","goal":"묵창 나루 주막에서 쉰다","need":{"at":["mukchang_ferry"],"tasks":[{"t":"rest","r":["mukchang_ferry"],"n":1}]},"lines":[{"s":null,"t":"밤이 깊어 문을 두드리는 소리가 났다. 다온이 공책 한 권을 가슴에 안고 서 있었다. 맨발이었다."},{"s":"q:mk_daon","t":"글자 배우고 싶어요."},{"s":"q:mk_daon","t":"제 이름 쓸 줄은 알아요. 근데 자꾸 까먹어요. 쓰고 나서 보면 이상한 글자가 돼 있어요."},{"s":null,"t":"공책 첫 장에는 「다온」이 스무 번쯤 적혀 있었다. 뒤로 갈수록 획이 흔들렸고, 마지막 몇 개는 다른 글자처럼 보였다."},{"s":null,"t":"아이는 공책을 내 앞에 내밀다 말고, 내 얼굴을 올려다보았다."},{"s":"q:mk_daon","t":"조사원 님 이름은 뭐예요?"},{"s":null,"t":"나는 이름을 알려 주었다. 다온은 혀끝으로 한 번 굴려 보고, 붓을 고쳐 쥐었다."},{"s":null,"t":"아이가 내 이름을 따라 썼다. 획 하나가 빠진, 삐뚤빼뚤한 글씨였다."},{"s":"q:mk_daon","t":"{이름} 님."},{"s":null,"t":"아이가 고개를 들고 한 번 더 불렀다. 그 소리가 이상하게 오래 남았다."},{"s":null,"t":"다온은 공책을 가슴에 다시 끌어안고, 처음으로 웃었다."},{"s":"q:mk_daon","t":"이제 안 까먹어요. 적었으니까."}],"reward":{"xp":6960}},{"quest_id":"mkq_1","step":5,"title":"장부와 종이","goal":"묵창 나루 주막의 희수에게 돌아간다","need":{"at":["mukchang_ferry"]},"lines":[{"s":null,"t":"희수는 나루 주막 구석에서 촛불 하나에 기대 명부를 대조하고 있었다. 맞은편 자리에 낯선 사내가 다리를 꼬고 앉아 있었다."},{"s":null,"t":"검은 도포에 연꽃 매듭. 손가락 사이에서 엽전 한 닢이 쉬지 않고 굴렀다. 희수는 그쪽을 한 번도 보지 않고 붓만 놀리고 있었다."},{"s":null,"t":"내가 들어서자, 사내가 고개를 돌렸다."},{"s":"q:mk_wolha","t":"아, 오셨네. 서리님이 하도 말을 안 해 줘서, 직접 기다리고 있었지."},{"s":"q:mk_hisu","t":"흑련회 분이 정청 조사 기록을 볼 이유는 없습니다."},{"s":"q:mk_wolha","t":"이유야 많죠. 이 동네 먹귀, 우리 쪽에선 다 값이 붙어 있거든요. 그런데 오늘 하나가 흩어졌다길래."},{"s":null,"t":"사내의 눈이 내 손끝에 멎었다. 먹 한 점. 손가락 사이에서 구르던 엽전이 멈췄다."},{"s":"q:mk_wolha","t":"……아. 범인이 여기 있었네."},{"s":"q:mk_wolha","t":"우리 쪽 물건을, 그것도 오늘 들어온 것 중에 제일 값나가던 놈을 흩어 버린 사람이. 이렇게 멀쩡한 얼굴로."},{"s":null,"t":"사내는 웃었다. 그러고는 몸을 돌려, 희수가 붙들고 있는 명부를 턱짓으로 가리켰다."},{"s":"q:mk_wolha","t":"그러니까 그 기록 좀 보자는 거였는데. 서리님은 한 장을 안 넘겨 주시네."},{"s":"q:mk_wolha","t":"종이 위에 적힌 글자 몇 개가 그렇게 대단합니까? 잠깐 들여다보는 것도 안 된다니."},{"s":null,"t":"희수의 붓이 그제야 멈췄다. 고개도 들지 않고 대답했다."},{"s":"q:mk_hisu","t":"정청 기록은 값을 매기라고 있는 게 아닙니다. 적어도 당신이 값을 매기는 것보다는 신중하게 다룹니다."},{"s":"q:mk_wolha","t":"하하. 이 사람 진짜 재미없네."},{"s":null,"t":"사내는 일어나 내 앞으로 왔다. 가까이서 보니 웃는 눈인데 웃고 있지 않았다."},{"s":"q:mk_wolha","t":"여기선 월하라고들 불러요, 조사원. 한동안 자주 볼 거예요. 이 서리님이 싫어하든 말든."},{"s":null,"t":"월하는 엽전을 튕겨 받아 쥐고, 휘파람을 불며 주막을 나갔다. 희수는 그 등이 문밖 어둠에 묻힐 때까지 눈을 떼지 않았다. 그러고 나서야 붓을 내려놓았다."},{"s":"q:mk_hisu","t":"……흑련회가 벌써 냄새를 맡았군요."},{"s":null,"t":"희수는 명부 맨 뒷장을 펼쳐 내 앞으로 밀었다. 나루 바깥, 넓은 빈칸 하나에 먹으로 테가 둘려 있었다."},{"s":"q:mk_hisu","t":"오늘 같은 먹귀는 원래 마을에 들어오지 않습니다. 정청은 오래전부터 저것들을 외곽 빈칸 벌판에 가둬 두었어요."},{"s":"q:mk_hisu","t":"그런데 석 달 전부터 테 밖으로 새어 나와 마을까지 흘러들기 시작했습니다. 오늘처럼 사람한테 붙은 건 처음이고요."},{"s":"q:mk_hisu","t":"내일, 벌판을 보러 가야겠어요. 테가 어디서 터졌는지."}],"reward":{"gil":420,"items":{"name_ink_charm":2,"erased_plate":2}}},{"quest_id":"mkq_2","step":1,"title":"데려갈 수 없는 아이","goal":"빈칸 벌판 어귀에서 희수를 만난다","need":{"at":["blank_field"]},"lines":[{"s":null,"t":"벌판 어귀에 닿았을 때, 등 뒤에서 익숙한 발소리가 났다. 희수가 걸음을 멈추고 한숨을 쉬었다. 돌아보지 않아도 누군지 안다는 얼굴로, 천천히 뒤를 돌아보았다."},{"s":"q:mk_hisu","t":"다온아."},{"s":null,"t":"다온이 공책을 끌어안은 채 우뚝 섰다. 들킨 줄 알면서도 도망가지 않았다."},{"s":"q:mk_daon","t":"저도 글 배우잖아요. {이름} 님이 이름 알려 주면 제가 적을게요. 그럼 안 까먹잖아요."},{"s":"q:mk_hisu","t":"여긴 아이가 올 곳이 아니야."},{"s":"q:mk_daon","t":"마을에 있어도 걔들 와요. 어젯밤에도 창문에 붙어 있었어요."},{"s":null,"t":"희수의 입술이 굳게 닫혔다. 반박하지 못했다. 한참 아이를 내려다보다가, 몸을 숙여 아이의 옷깃을 여며 주었다."},{"s":"q:mk_hisu","t":"……내 뒤에서 한 걸음도 떨어지지 마."},{"s":null,"t":"다온이 힘차게 고개를 끄덕였다. 희수는 아이를 제 등 뒤로 세우고, 나를 보았다."},{"s":"q:mk_hisu","t":"조사원, 저는 여기 어귀에서 다온을 지키고 있겠습니다. 그동안 벌판에서 먹귀를 찾아 주세요."},{"s":"q:mk_hisu","t":"정청은 지금까지 이 벌판을 가둬 두기만 했습니다. 흩뜨려도 다시 모이고, 이름을 들을 수 있는 사람이 없었으니까요."}],"reward":{}},{"quest_id":"mkq_2","step":2,"title":"지나가는 이름들","goal":"빈칸 벌판에서 떠도는 먹귀를 3번 풀어 보낸다","need":{"at":["blank_field"],"tasks":[{"t":"win","m":["mk_field_1"],"n":3}]},"lines":[{"s":null,"t":"이름을 부를 때마다 먹귀는 형체를 잃고, 내 몸을 꿰뚫듯 지나갔다. 그때마다 손끝이 얼음물에 담근 것처럼 저렸다."},{"s":null,"t":"세 번째쯤에서 손톱 밑이 검게 물들었다. 털어도 떨어지지 않았다."},{"s":null,"t":"어귀로 돌아오자 다온이 희수 등 뒤에서 고개를 쑥 내밀었다. 벌써 공책을 펼쳐 들고 있었다."},{"s":"q:mk_daon","t":"방금 그 사람은 이름이 뭐였어요?"},{"s":null,"t":"나는 이름을 알려 주었다. 다온은 자기 이름 연습 옆에, 그 이름을 또박또박 적었다."},{"s":"q:mk_daon","t":"그다음 사람은요? 어떤 사람이었어요? 아까 그 사람보다 키가 커 보였는데."},{"s":null,"t":"나는 그 사람의 이름도 알려 주었다. 아이는 이름 옆에 「키가 큼」이라고 작게 덧붙였다. 무엇이라도 남겨 두려는 것처럼."},{"s":null,"t":"희수는 내 손을 흘끗 내려다보았다. 표정 하나 바뀌지 않았다."},{"s":"q:mk_hisu","t":"조사원, 손은 괜찮습니까."},{"s":null,"t":"괜찮다고 했다. 희수는 한 번 더 내 손을 보고, 대꾸 없이 장부에 무언가를 적었다."},{"s":null,"t":"저릿한 손끝을 내려다보다가, 불현듯 깨달았다. 이 벌판의 이름들을 들을 수 있는 사람은 나 하나였다. 내가 부르지 않으면, 아무도 부르지 않는다."},{"s":null,"t":"그때 벌판 한가운데서 낮게 우는 소리가 바람을 타고 왔다. 여럿이 한꺼번에 이름을 웅얼거리는 소리. 희수가 다급히 장부를 덮었다."},{"s":"q:mk_hisu","t":"안쪽에 큰 무리가 있어요. 저렇게 한데 몰려 우는 건 처음 듣습니다. 조심해서 가 주세요."}],"reward":{"xp":4854}},{"quest_id":"mkq_2","step":3,"title":"몰아오는 사람","goal":"빈칸 벌판 안쪽을 3번 탐색한다","need":{"at":["blank_field"],"tasks":[{"t":"search","r":["blank_field"],"n":3}]},"lines":[{"s":null,"t":"벌판 한가운데서 먹귀들이 한쪽으로 쏠리고 있었다. 무언가에 쫓기는 양 떼처럼."},{"s":null,"t":"그 뒤에 월하가 있었다. 엽전을 꿴 끈을 휘휘 돌리며, 먹귀를 내 쪽으로 몰고 있었다. 나를 보자 반가운 사람을 만난 듯 손을 흔들었다."},{"s":"q:mk_wolha","t":"왔어요? 마침 잘 왔네. 이쪽 무리, 원래는 오늘 우리 쪽에서 실어 갈 물건이었거든요."},{"s":"q:mk_wolha","t":"근데 그쪽이 하나씩 흩어 버리니까 아깝잖아. 그 이름들, 우리한텐 다 값이 나가는 건데."},{"s":"q:mk_wolha","t":"정청이 이름을 거두면, 남은 식구들은 그 사람 얼굴도 못 떠올려요. 잃었다는 것만 알지. 근데 먹귀는 기억해요. 미련이 남았으니까."},{"s":"q:mk_wolha","t":"그걸 맡아 뒀다가 찾는 사람한테 돌려주는 거죠. 어머니 목소리 한 마디에 쌀 두 섬. 아이 얼굴 한 번에 논 한 마지기. 이래 봬도 싸게 쳐 주는 거예요."},{"s":"q:mk_wolha","t":"그런데 그쪽이 불러 버리면, 그게 다 그쪽 손끝으로 들어가잖아. 남의 장사를 아주 공짜로 망치시네."},{"s":null,"t":"사내는 웃으며 말했다. 그런데 엽전 끈을 돌리는 손은 멈추지 않았다."},{"s":null,"t":"밀려든 이름이 한꺼번에 가슴을 두드렸다. 나는 하나씩 불렀다. 검은 얼룩이 손등을 넘어 손목까지 번졌다."},{"s":null,"t":"월하는 그 모습을 보며 품에서 장부를 꺼내 붓을 놀렸다. 몇 번째인지, 어디가 물들었는지."},{"s":"q:mk_wolha","t":"다섯. 여섯. 손목까지. 아직 서 있네. 생각보다 튼튼한 그릇인데요, 조사원."},{"s":null,"t":"뒤따라온 희수가 다온을 등 뒤로 감추며 앞으로 나섰다. 목소리가 낮고 단단했다."},{"s":"q:mk_hisu","t":"그만두세요. 정청 조사 구역입니다."},{"s":"q:mk_wolha","t":"서리님은 숨 쉬는 것도 규정에 적힌 순서대로 합니까?"},{"s":"q:mk_hisu","t":"당신은 거래할 수 없는 것엔 관심도 없으신가 보군요."},{"s":"q:mk_wolha","t":"적어도 재미없는 일에 시간을 버리진 않죠."},{"s":null,"t":"그 틈에 다온이 희수 등 뒤에서 빠져나와 내 앞으로 뛰어들었다. 작은 몸으로 팔을 벌리고, 월하를 올려다보았다."},{"s":"q:mk_daon","t":"아저씨는 왜 자꾸 따라와요?"},{"s":"q:mk_wolha","t":"아저씨라. 이쪽은 아직 그렇게 불릴 나이는 아닌데."},{"s":"q:mk_daon","t":"그럼 더 따라오지 마요."},{"s":"q:mk_wolha","t":"꼬맹아, 네가 쫓아낼 수 있는 사람인지부터 생각해 보렴."},{"s":null,"t":"다온은 입술을 삐죽이다가, 무언가 떠오른 듯 눈을 가늘게 떴다."},{"s":"q:mk_daon","t":"……월하가 진짜 이름이에요?"},{"s":"q:mk_wolha","t":"부르는 이름이지. 진짜는 맡겨 놨어."},{"s":"q:mk_daon","t":"누구한테요?"},{"s":"q:mk_wolha","t":"너보다 훨씬 무서운 사람한테."},{"s":null,"t":"다온은 물러서지 않았다. 공책을 가슴에 꼭 끌어안고, 숨을 씩씩 몰아쉬며 월하를 노려보았다. 월하는 그게 재미있다는 듯 웃었다."},{"s":null,"t":"희수는 그런 월하를 진절머리 난다는 눈으로 한 번 쳐다보고는, 더 상대하지 않았다. 다온의 손목을 잡아 끌어당기고, 다른 손으로 내 어깨를 돌려 벌판 바깥쪽으로 가볍게 떠밀었다."},{"s":"q:mk_hisu","t":"가죠, 조사원. 해가 집니다."},{"s":null,"t":"끌려가던 다온이 고개를 돌려 내 소매를 잡아당겼다."},{"s":"q:mk_daon","t":"{이름} 님, 돌아가는 길에 보여 줄 데가 있어요. 꼭 같이 가 줘요."}],"reward":{"xp":4854}},{"quest_id":"mkq_2","step":4,"title":"이름 없는 위패","goal":"다온을 따라 빈칸 벌판의 이름 없는 사당을 찾는다","need":{"at":["blank_field"],"tasks":[{"t":"search","r":["blank_field"],"n":2}]},"lines":[{"s":null,"t":"마을과 벌판 사이에 지붕이 내려앉은 작은 사당이 있었다. 안에는 위패가 빽빽했다. 대부분 아무 글자도 없었다."},{"s":null,"t":"다온은 익숙하게 문지방을 넘었다. 혼자 몇 번이고 와 본 걸음이었다."},{"s":"q:mk_daon","t":"정청이 이름을 가져간 사람들은 제사를 못 지내요. 그래서 동네 사람들이 몰래 여기 세웠대요."},{"s":"q:mk_daon","t":"정청이 가져간 이름은 아무도 기억이 안 나서 못 쓴대요. 그래서 그냥 나무만 세워 둔 거예요. 누가 누군지는 세운 사람도 이제 몰라요."},{"s":null,"t":"아이는 맨 끝, 유난히 검게 바랜 위패 앞에 섰다. 그 하나에만 글자가 남아 있었다."},{"s":null,"t":"「서하」."},{"s":"q:mk_daon","t":"이건 읽을 수 있어요. 제가 지금 사는 집 말이에요, 원래 살던 사람 이름이래요."},{"s":null,"t":"아이는 위패를 한참 올려다보다가, 목소리를 낮췄다."},{"s":"q:mk_daon","t":"그 집에 들어간 날부터요, 밤마다 창밖에서 누가 이 이름을 불러요. 서하, 서하, 하고. 제 이름은 안 부르고 꼭 이 이름만요."},{"s":"q:mk_daon","t":"마을에서 이 이름 읽을 수 있는 데는 여기밖에 없어요. 그래서 {이름} 님 데려오고 싶었어요."},{"s":"q:mk_daon","t":"{이름} 님은 그거들 이름 들을 수 있잖아요. 이 사람도 그거 됐어요? 그래서 밤마다 저 찾아오는 거예요?"},{"s":null,"t":"나는 위패 앞에서 귀를 기울였다. 가슴 안쪽이 고요했다. 이 나무에서는 아무 이름도 들리지 않았다."},{"s":null,"t":"그렇다면 밤마다 창밖에서 서하를 부르는 것은, 누구인가."},{"s":null,"t":"나는 대답하지 못했다. 다온은 내 얼굴을 보고, 더 묻지 않았다."},{"s":null,"t":"뒤에서 따라 들어온 월하가 위패들을 심드렁하게 훑었다. 그러다 「서하」에서 눈이 멈췄다. 손가락 사이를 구르던 엽전 소리가 끊겼다."},{"s":null,"t":"그는 아무 말 없이 돌아서 나갔다."},{"s":null,"t":"희수는 그런 월하를 한차례 곁눈질했다. 그러고는 나를 향해 손을 내밀었다."},{"s":"q:mk_hisu","t":"……조사원, 오늘은 여기까지 하죠. 마을로 돌아가서 손을 좀 보여 주세요."}],"reward":{"xp":4854}},{"quest_id":"mkq_2","step":5,"title":"지워지지 않는 얼룩","goal":"묵창 나루로 돌아가 희수에게 손을 보인다","need":{"at":["mukchang_ferry"]},"lines":[{"s":null,"t":"우물물에 손을 씻었다. 몇 번을 문질러도 손끝부터 손등까지 번진 먹은 빠지지 않았다."},{"s":null,"t":"희수가 등불을 가까이 대고 내 손을 들여다보았다. 손가락 마디를 하나씩 눌러 보고, 장부에 무언가를 적었다."},{"s":"q:mk_hisu","t":"정청 기록에는 이걸 「묵화」라고 적어요. 풀어 보낸 이름이 지나가며 남기는 먹이에요."},{"s":"q:mk_hisu","t":"아프지는 않습니까."},{"s":null,"t":"아프지 않다고 했다. 정말이었다. 그게 더 이상했다."},{"s":null,"t":"우물가 돌 위에 앉아 공책을 정리하던 다온이 고개를 들었다."},{"s":"q:mk_daon","t":"{이름} 님."},{"s":null,"t":"대답이 한 박자 늦었다. 다온이 부른 것이 나라는 걸 알아차리기까지, 숨 한 번이 걸렸다."},{"s":"q:mk_daon","t":"……{이름} 님?"},{"s":null,"t":"아이의 목소리가 아주 조금 떨렸다. 나는 웃으며 고개를 돌렸다. 다온은 웃지 않았다. 공책을 쥔 손가락 끝이 하얗게 질려 있었다."},{"s":null,"t":"희수가 등불을 내려놓았다. 다온 곁으로 가 그 앞에 쪼그려 앉고, 아이의 손에서 공책을 받아 가지런히 덮어 주었다."},{"s":"q:mk_hisu","t":"다온아. 오늘은 들어가 자렴. 조사원은 피곤해서 그런 거야."},{"s":null,"t":"다온은 나를 한 번 더 보았다. 그리고 고개를 끄덕이고, 몇 번이고 뒤를 돌아보며 집으로 들어갔다."},{"s":null,"t":"아이의 방에 불이 꺼진 것을 보고 나서야, 희수는 나를 돌아보았다. 목소리를 낮췄다."},{"s":"q:mk_hisu","t":"……방금 같은 일이 또 있으면 말해 주세요. 조사원 혼자 넘기지 마시고요."},{"s":"q:mk_hisu","t":"내일은 먹비 숲을 봐야겠어요. 먹귀가 벌판으로 흘러드는 길이 그 숲을 지납니다. 테가 터진 곳도 아마 그쪽일 거예요."}],"reward":{"gil":430,"items":{"meokgwi_incense":2,"blank_hanji":3}}},{"quest_id":"mkq_3","step":1,"title":"남의 꿈","goal":"묵창 나루에서 아침을 맞는다","need":{"at":["mukchang_ferry"]},"lines":[{"s":null,"t":"꿈을 꾸었다. 처음 보는 마을, 처음 보는 눈. 누군가의 어머니가 아궁이 앞에서 내 이름이 아닌 이름을 불렀다."},{"s":null,"t":"깨어나도 그 목소리가 귓가에 남아 있었다. 나는 그 사람을 모른다. 그런데 그 목소리가 얼마나 따뜻했는지는 안다."},{"s":null,"t":"소매를 걷었다. 먹 무늬가 손목을 지나 팔뚝까지 올라와 있었다."},{"s":"q:mk_daon","t":"그거 뭐예요?"},{"s":null,"t":"다온이 문간에 서 있었다. 아침밥을 가져온 모양이었다. 소반을 든 채 얼굴이 하얗게 질렸다."},{"s":"q:mk_daon","t":"다쳤어요? 서리님한테 약 달라고 할게요. 금방 갔다 올게요."},{"s":null,"t":"괜찮다고 했다. 아이는 듣지 않았다. 문 밖으로 반쯤 나가다 돌아와, 내 팔을 다시 한 번 보고, 입술을 깨물었다."},{"s":"q:mk_daon","t":"……안 괜찮은 거 알아요."},{"s":null,"t":"소반을 문지방에 내려놓은 아이는 그대로 골목으로 뛰어나갔다. 부를 틈도 없었다."},{"s":null,"t":"얼마 지나지 않아 다급한 발소리가 둘 돌아왔다. 다온이 희수의 소매를 붙잡고 끌다시피 데려오고 있었다. 희수는 겉옷도 다 여미지 못한 차림이었다."},{"s":null,"t":"희수는 문간에서 숨을 고르고, 내 팔을 보았다. 아무 말 없이 다가와 소매를 더 걷어 올리고, 먹이 번진 끝을 손가락으로 따라갔다."},{"s":"q:mk_daon","t":"약 있죠? 서리님, 약 있잖아요."},{"s":null,"t":"희수는 대답하기 전에 다온을 한 번 보았다. 아이 앞에서 할 말과 하지 않을 말을 가르는 눈이었다."},{"s":"q:mk_hisu","t":"……이건 약으로 듣는 상처가 아니야, 다온아. 대신 무엇인지는 알아낼 수 있어."},{"s":null,"t":"희수는 내 팔뚝의 먹을 한참 들여다보다가, 미간을 좁혔다. 무언가 떠오른 얼굴이었다."},{"s":"q:mk_hisu","t":"조사원, 먹비 숲 이야기를 들은 적 있으십니까. 비가 오지 않는데도 잎마다 먹물이 맺힌다는 숲이에요. 먹귀가 벌판으로 흘러드는 길이 그 숲을 지나고요."},{"s":"q:mk_hisu","t":"이 먹이 그 숲의 먹과 같은 것인지 대 봐야겠어요. 같다면, 테가 터진 곳도 그 숲 어딘가일 겁니다."},{"s":"q:mk_hisu","t":"숲에서 먹비 맞은 잎을 몇 장 거둬 와 주시겠어요. 저는 그동안 서고 기록을 찾아보겠습니다."}],"reward":{}},{"quest_id":"mkq_3","step":2,"title":"먹 위에 쓴 이름","goal":"먹비 숲에서 먹비 이끼(먹비 맞은 잎) 3개를 거둬 묵창 나루로 가져온다","need":{"at":["mukchang_ferry"],"tasks":[{"t":"gather","items":["meokbi_moss"],"r":["meokbi_forest"],"n":3}]},"lines":[{"s":null,"t":"숲은 비가 오지 않는데도 젖어 있었다. 잎마다 검은 물방울이 맺혀 떨어졌다. 숲 전체가 천천히 지워지고 있는 것 같았다."},{"s":null,"t":"나루로 돌아와 거둔 잎을 희수 앞에 내려놓았다. 희수는 잎 한 장을 집어 등불에 비추고, 내 팔 옆에 나란히 대 보았다."},{"s":null,"t":"잎에 맺힌 먹과 내 팔의 먹 무늬는, 빛을 받는 결까지 같았다."},{"s":null,"t":"희수는 잎을 내려놓았다. 곁에서 숨을 죽이고 지켜보던 다온을 한 번 보고, 다시 내게로 눈을 돌렸다. 입을 열었다가, 닫았다."},{"s":"q:mk_hisu","t":"……같아요. 자세한 건 밤에 따로 말씀드릴게요."},{"s":null,"t":"희수가 서고 기록을 챙기러 나가자, 다온이 내 손을 잡으려다 멈췄다. 손등의 먹을 보고서."},{"s":"q:mk_daon","t":"만지면 저한테도 옮아요?"},{"s":null,"t":"아니라고 했다. 아이는 그래도 한참 망설이다가, 손가락 끝으로만 살짝 내 손등을 건드렸다."},{"s":null,"t":"해가 지고, 다온은 공책을 들고 왔다. 첫 장의 삐뚤빼뚤한 내 이름 아래, 조금 반듯해진 글씨로 다시 이름을 적어 두었다."},{"s":null,"t":"그리고 붓에 먹을 찍어, 내 팔의 먹 무늬 위에 내 이름을 썼다. 붓끝이 간지러웠다."},{"s":"q:mk_daon","t":"이러면 안 지워지죠?"},{"s":null,"t":"나는 대답하지 못했다. 아이는 대답을 기다리지 않고, 마지막 획을 꾹 눌러 썼다."},{"s":null,"t":"다온이 제 집으로 돌아가고 한참 뒤였다. 아이 방 쪽 창밖에서, 바람 소리와는 다른 소리가 났다."},{"s":null,"t":"「서하.」"},{"s":null,"t":"낮고 지친 목소리였다. 한 번, 조금 있다 또 한 번. 다온이 사당에서 흉내 내던 그 박자였다."},{"s":null,"t":"문을 열고 나가 보았다. 골목에는 아무도 없었다. 창틀 아래 흙바닥에, 먹물이 떨어진 자국만 몇 점 남아 있었다."},{"s":null,"t":"팔의 먹과 같은 빛이었다. 낮에 희수가 밤에 따로 말하겠다던 것이 떠올랐다. 이런 일이 또 있으면 혼자 넘기지 말라던 말도."},{"s":null,"t":"나는 소매를 내리고, 희수가 머무는 주막으로 걸음을 옮겼다. 팔에 쌓인 먹이 무엇인지, 창밖의 저것이 무엇인지 — 둘 다 오늘 밤 안에 들어야 했다."}],"reward":{"xp":5073}},{"quest_id":"mkq_3","step":3,"title":"털어 내는 법","goal":"밤에 묵창 나루 주막의 희수에게 팔을 보이고 창밖 목소리를 알린다","need":{"at":["mukchang_ferry"]},"lines":[{"s":null,"t":"희수는 주막 뒷방에서 서고 기록을 펼쳐 놓고 기다리고 있었다. 나는 창밖의 목소리 이야기를 먼저 했다. 희수는 붓을 든 채 한동안 움직이지 않았다."},{"s":"q:mk_hisu","t":"……그 이야기는, 내일 보여 드릴 기록과 같이 하죠."},{"s":null,"t":"나는 소매를 걷었다. 다온에게는 말하지 말아 달라고 했다. 아이가 내 팔 위에 써 준 이름이 등불 아래 번들거렸다."},{"s":null,"t":"희수의 눈이 그 글씨에서 멈췄다. 한참 말이 없었다. 손에 쥔 붓이 종이 위에서 마르고 있었다."},{"s":"q:mk_hisu","t":"낮에 본 잎과 같은 먹이에요. 먹비 숲의 먹은, 이름이 흩어지며 떨어뜨린 찌꺼기입니다. 조사원 팔에 쌓이는 것도 같은 거예요."},{"s":"q:mk_hisu","t":"털어 낼 수 있어요. 정청에 그 절차가 있습니다. 먹을 털어 내면 묵화는 멈춰요."},{"s":"q:mk_hisu","t":"다만 먹 안에 든 것도 같이 사라집니다."},{"s":"q:mk_hisu","t":"조사원이 풀어 보낸 사람들의 마지막 기억이에요. 그 사람들이 다시 죽는 건 아니에요. 그런데 조사원은 그 사람들을 기억하지 못하게 돼요. 목소리도, 얼굴도. 전부요."},{"s":null,"t":"꿈속의 어머니 목소리가 떠올랐다. 처음 본 눈, 아궁이 냄새."},{"s":null,"t":"나는 털어 내지 않겠다고 했다."},{"s":"q:mk_hisu","t":"……그럴 줄 알았어요."},{"s":null,"t":"희수는 말리지 않았다. 대신 펼쳐 둔 기록 맨 뒷장을 내 쪽으로 돌렸다. 붉은 줄이 그어진 오래된 지시문이었다."},{"s":"q:mk_hisu","t":"정청은 조사원이 발견된 날부터 이걸 준비해 왔어요. 빈 고리를 가진 조사원이 요화를 일으키면 쓸 봉인진. 육신과 명줄을 붙잡고, 매듭에 쌓인 먹을 함께 거둬 가는 진이에요."},{"s":"q:mk_hisu","t":"봉인은 잘 들을 거예요. 조사원의 매듭은 한 번 남의 손으로 묶인 거라, 다시 묶는 것도 잘 받아요."},{"s":null,"t":"희수는 \"함께 거둬 가는\"이라는 말을 할 때 눈을 내리깔았다."},{"s":"q:mk_hisu","t":"예전에도 조사원 같은 사람이 있었습니다. 그때는 이 진이 없었어요."},{"s":"q:mk_hisu","t":"서율 조사원. 서고에 그분 보고서가 몇 장 남아 있어요. 오늘 밤 사람을 보내 정청 서고에서 가져오게 할 테니, 내일 이 주막으로 와 주세요. 거기서 보여 드릴게요."},{"s":null,"t":"문 밖, 처마 아래에서 누군가 혼잣말을 했다."},{"s":"q:mk_wolha","t":"……그거 하나에 쌀 두 섬인데."},{"s":null,"t":"늘 하던 장사꾼 말투였다. 발소리가 멀어졌다. 희수는 문 쪽을 한 번 보고, 아무 말도 하지 않았다."}],"reward":{}},{"quest_id":"mkq_3","step":4,"title":"서율의 보고서","goal":"이튿날 묵창 나루 주막에서 희수에게 옛 보고서를 받는다","need":{"at":["mukchang_ferry"]},"lines":[{"s":null,"t":"이튿날 주막으로 가자, 희수가 정청 서고에서 가져온 보고서를 펼쳐 놓고 있었다. 보고서는 누렇게 바래 있었다. 그런데 글씨만은 칼로 새긴 것처럼 또렷했다."},{"s":null,"t":"구조한 주민마다 이름이 빠짐없이 적혀 있었다. 이름 옆에는 구조 당시의 상태, 식구, 마지막으로 본 곳까지."},{"s":"q:mk_hisu","t":"서율 조사원은 늘 현장에 먼저 들어갔대요. 동료들 이름을 하나도 안 틀리고 외웠고요. 보고서에 사람 이름을 이렇게까지 적는 분은 그분밖에 없었어요."},{"s":null,"t":"한 장에 정청의 이름 거둠 결정에 대한 이의가 붙어 있었다."},{"s":null,"t":"「대상자 서하의 이름을 거두는 것은 재검토를 요청함. 해당 대상은 아직 자신의 이름을 기억하고 있음.」"},{"s":null,"t":"서하. 사당 맨 끝의 위패."},{"s":null,"t":"그리고 다온의 창밖에서 밤마다 불리는 이름."},{"s":"q:mk_hisu","t":"어젯밤 그 목소리가 누구인지는 저도 모릅니다. 다만 기록에서 이 이름을 이렇게까지 붙든 사람은 한 명뿐이에요."},{"s":null,"t":"희수는 보고서 귀퉁이의 작성자 이름을 손끝으로 짚었다. 「서율」."},{"s":null,"t":"보고서 맨 아래, 같은 필체로 짧게."},{"s":null,"t":"「이름을 잊기 전에 한 번 더 확인할 것.」"},{"s":"q:mk_hisu","t":"그 뒤 몇 장은 기록이 불완전해요. 왜 현장을 떠나셨는지, 그 뒤에 어떻게 되셨는지는 없어요."},{"s":"q:mk_hisu","t":"숲 안쪽에 그분이 쓰던 조사원 숙소가 아직 있을 거예요."},{"s":null,"t":"문득 고개를 드니 월하가 기둥에 기대 서 있었다. 언제부터 듣고 있었는지 몰랐다. 그는 보고서의 「서하」라는 글자를 오래 보았다."},{"s":"q:mk_wolha","t":"……숲 안쪽은 먹귀가 많아요. 혼자 가면 손목 정도로는 안 끝날걸요, 조사원."},{"s":null,"t":"놀리는 말투였다. 그런데 장부는 펴지 않았다."}],"reward":{}},{"quest_id":"mkq_3","step":5,"title":"벽의 이름","goal":"먹비 숲 안쪽을 3번 탐색해 옛 조사원 숙소를 찾는다","need":{"at":["meokbi_forest"],"tasks":[{"t":"search","r":["meokbi_forest"],"n":3}]},"lines":[{"s":null,"t":"숙소는 숲에 먹혀 있었다. 문틀에 이끼가 끼고, 지붕 틈으로 먹비가 샜다."},{"s":null,"t":"안으로 들어서자 숨이 막혔다. 네 벽이 전부 글씨였다."},{"s":null,"t":"「서하」. 「서하」. 「서하」. 수백 번."},{"s":null,"t":"처음은 반듯했다. 보고서와 같은 칼 같은 필체. 뒤로 갈수록 흔들렸고, 획이 빠졌고, 끝내는 글자라고 부를 수 없는 먹 자국이 되었다."},{"s":null,"t":"구석에 단 한 번, 「서율」."},{"s":null,"t":"그 아래 한 줄."},{"s":null,"t":"「털어 내면 그들이 두 번 죽는다. 그러니 내가 다 붙들고 가겠다.」"},{"s":null,"t":"내가 어제 한 말과 같았다. 글자 하나 다르지 않았다."},{"s":null,"t":"바닥에 작은 종이패가 떨어져 있었다. 아이 손바닥만 한 크기. 「서하」. 그 옆에 접힌 쪽지."},{"s":null,"t":"「오늘은 서하가 내 이름을 먼저 불렀다.」"},{"s":null,"t":"나는 쪽지를 한참 들고 서 있었다. 지켜야 할 사람이 아니었다. 서로의 이름을 불러 주던 사람이었다."}],"reward":{"xp":5073}},{"quest_id":"mkq_3","step":6,"title":"같은 서술","goal":"숙소를 나와 먹비 숲을 한 번 더 탐색한다","need":{"at":["meokbi_forest"],"tasks":[{"t":"search","r":["meokbi_forest"],"n":1}]},"lines":[{"s":null,"t":"숲길에 사람 하나가 서 있었다. 얼굴이 없었다. 먹으로 그린 사람의 윤곽만 있었다."},{"s":null,"t":"내가 다가가자, 그것이 고개를 들었다."},{"s":"q:mk_shadow","t":"나는 걸음을 멈췄다."},{"s":"q:mk_shadow","t":"나는 그 이름을 들었다."},{"s":"q:mk_shadow","t":"나는 아직, 돌아갈 수 있었다."},{"s":null,"t":"등줄기가 서늘해졌다. 내가 나를 말할 때 쓰는 말이었다. 그것이 내 말투로 제 이야기를 하고 있었다."},{"s":"q:mk_shadow","t":"잘 골랐다. 나도 그렇게 골랐다."},{"s":null,"t":"서율을 아느냐고 물었다. 그림자는 대답하지 않았다. 먹으로 된 얼굴이 내 손을, 손등의 먹 무늬를, 그 위에 아이가 써 준 이름을 내려다보았다."},{"s":"q:mk_shadow","t":"그걸 버리지 마라."},{"s":null,"t":"그림자가 등을 돌렸다. 숲 저편, 묵창 나루 쪽을 향해 몇 걸음 걸어가며 낮게 중얼거렸다."},{"s":"q:mk_shadow","t":"……서하."},{"s":null,"t":"숨이 멎었다. 낮고 지친 목소리, 한 번 부르고 조금 있다 또 한 번 부르는 박자. 어젯밤 다온의 창밖에서 들은 그 목소리였다."},{"s":null,"t":"아이의 창밖에서 밤마다 서하를 부르던 것은, 이것이었다."},{"s":"q:mk_shadow","t":"서하."},{"s":null,"t":"나는 그를 불러 세우려 했다. 부를 이름이 없었다. 그림자는 먹비 속으로 번지듯 사라졌다. 젖은 흙 위에, 창틀 아래와 같은 먹 자국이 몇 점 남았다."}],"reward":{"xp":5073}},{"quest_id":"mkq_3","step":7,"title":"멈춘 붓","goal":"묵창 나루로 돌아간다","need":{"at":["mukchang_ferry"]},"lines":[{"s":null,"t":"나루로 돌아오자 다온이 달려왔다."},{"s":"q:mk_daon","t":"{이름} 님! 늦었어요. 서리님이 찾으러 간다고 했는데."},{"s":null,"t":"나는 아이 이름을 부르려 했다. 입에서 나온 건 다른 이름이었다. 서하."},{"s":null,"t":"다온이 멈춰 섰다. 나는 곧바로 고쳐 불렀다. 다온. 아이는 고개를 끄덕였지만, 웃음이 늦게 돌아왔다."},{"s":null,"t":"등 뒤에서 붓 소리가 멎었다. 월하였다. 장부를 펼친 채, 붓을 종이 위에 대고만 있었다."},{"s":"q:mk_daon","t":"또 적어요? 보여 줘요."},{"s":null,"t":"다온이 장부를 들여다보려 하자 월하가 탁 덮었다."},{"s":"q:mk_wolha","t":"남의 물건에 손대면 안 된다는 말도 못 배웠니, 꼬맹아?"},{"s":"q:mk_daon","t":"아저씨가 {이름} 님 괴롭히는 건 괜찮고요?"},{"s":"q:mk_wolha","t":"내가 괴롭히는 건 아니지. 어디까지 버티는지 보는 거야."},{"s":"q:mk_daon","t":"그게 괴롭히는 거잖아요."},{"s":null,"t":"월하는 웃었다. 대답은 없었다. 그날 밤 그는 장부를 한 번도 꺼내지 않았다."},{"s":"q:mk_hisu","t":"조사원. 정청에서 연락이 왔어요. 나루 사정이 나빠지고 있습니다. 먹귀가 빈칸 벌판에서 나루로 들어오는 길목부터 살펴봐 주세요. 어디로 새어 드는지 봐야 해요."}],"reward":{"gil":440,"items":{"meokbi_umbrella":2,"meokbi_moss":3}}},{"quest_id":"mkq_4","step":1,"title":"엉킴","goal":"묵창 나루에서 희수를 만난다","need":{"at":["mukchang_ferry"]},"lines":[{"s":null,"t":"나루가 변해 있었다. 낮인데도 사람들 뒤에 검은 형체가 하나씩 붙어 다녔다."},{"s":null,"t":"국밥집 노인은 죽은 아들의 어린 시절을 제 어린 시절이라고 말했다. 우물가 아낙은 물에 비친 제 얼굴을 낯설어하며, 다른 사람의 이름으로 자신을 소개했다."},{"s":null,"t":"문패의 글자들이 서로 겹쳐 번졌다. 한 집에 두 사람의 이름이, 세 사람의 이름이."},{"s":"q:mk_hisu","t":"정청은 이걸 「엉킴」이라고 적어요. 먹귀가 한곳에 너무 오래 머물러서, 산 사람 명줄까지 파고든 거예요."},{"s":"q:mk_hisu","t":"조사원, 다온은 어디 있어요? 벌판 길목을 살피고 오는 길에 아이 집에 들러 봐 주세요. 나루 안쪽, 문패가 다 지워진 집이에요."}],"reward":{}},{"quest_id":"mkq_4","step":2,"title":"다온 맞죠?","goal":"빈칸 벌판에서 나루로 들어오는 길목을 3번 탐색하고, 묵창 나루 안쪽 다온의 집에 간다","need":{"at":["mukchang_ferry"],"tasks":[{"t":"search","r":["blank_field"],"n":3}]},"lines":[{"s":null,"t":"벌판 길목을 살피고 나루로 돌아와, 문패가 다 지워진 집 앞에 섰다. 안에서 붓 소리가 났다. 다온은 마루에 엎드려 공책을 쓰고 있었다. 내가 들어가도 고개를 들지 않았다."},{"s":null,"t":"들여다보았다. 「다온」을 쓰려던 자리마다 「서하」가 적혀 있었다."},{"s":null,"t":"아이는 그걸 지우고, 다시 쓰고, 또 「서하」를 썼다. 손이 떨렸다."},{"s":"q:mk_daon","t":"이상해요. 손이 혼자 써요."},{"s":null,"t":"아이가 드디어 고개를 들었다. 눈이 붉었다."},{"s":"q:mk_daon","t":"저, 다온 맞죠?"},{"s":null,"t":"맞다고 했다. 이름을 불러 주었다. 다온. 아이의 어깨에서 힘이 빠졌다."},{"s":null,"t":"문간에서 월하가 공책을 내려다보고 있었다. 「서하」가 빼곡한 장. 그의 얼굴에서 웃음이 지워졌다."},{"s":"q:mk_wolha","t":"그 이름, 네 이름이 아니잖아."},{"s":"q:mk_daon","t":"알아요. 그러니까 제 이름 안 잊으려고 적는 거예요."},{"s":null,"t":"아이는 공책을 가슴에 끌어안았다. 월하는 한동안 아무 말도 하지 않았다. 처음으로 아이를 놀리지 않았다."},{"s":"q:mk_hisu","t":"조사원. 정청 명부가 왔습니다. 잠깐 나와 주세요."}],"reward":{"xp":4144}},{"quest_id":"mkq_4","step":3,"title":"정청의 결정","goal":"묵창 나루의 희수에게 간다","need":{"at":["mukchang_ferry"]},"lines":[{"s":null,"t":"희수의 손에 봉인된 명부 한 장이 들려 있었다. 붉은 끈이 매여 있었다."},{"s":"q:mk_hisu","t":"엉킴의 가운데에 다온이 사는 집이 있어요. 서하의 이름이 남은 집. 다온은 그 집에 살면서 서하의 이름과 제일 깊게 엉켜 버렸어요."},{"s":"q:mk_hisu","t":"정청은 다온의 이름을 거둬 그 고리를 끊기로 했습니다. 마을 먹귀가 다 사라지는 건 아니에요. 다만 더 번지지는 않아요."},{"s":null,"t":"희수는 명부를 펼치지 않았다. 끈을 쥔 손가락 마디가 하얬다."},{"s":"q:mk_hisu","t":"저는 이 아이 이름을 석 달째 미뤄 왔어요. 이제는 미룰 수가 없어요."},{"s":"q:mk_wolha","t":"그 아이 이름도 거둘 겁니까?"},{"s":null,"t":"월하가 언제 왔는지, 희수 뒤에 서 있었다."},{"s":"q:mk_hisu","t":"정청의 결정입니다."},{"s":"q:mk_wolha","t":"서리님은 늘 그렇게 말하더라."},{"s":"q:mk_hisu","t":"당신은 늘 책임질 생각도 없는 사람처럼 말하고요."},{"s":"q:mk_wolha","t":"책임? 서리님이 지는 책임이란 게, 붓으로 이름 하나 지우고 \"결정이었다\" 한 줄 다는 거잖아요."},{"s":"q:mk_hisu","t":"그 한 줄 때문에 마을 사람 쉰이 자기 이름으로 살아요. 당신 장부에는 그런 줄이 있습니까."},{"s":null,"t":"월하는 웃었다. 이번에는 농담을 덧붙이지 않았다."},{"s":null,"t":"나는 물었다. 먹귀를 모두 풀어 보내면 다온의 이름을 거둘 까닭도 없어지느냐고."},{"s":"q:mk_hisu","t":"……이론으로는요. 마을 먹귀는 전부 명부 탑에 모여 있어요. 정청이 거둔 이름의 원부를 쌓아 두던 옛 탑이에요. 거기 있는 걸 한꺼번에 조사원의 빈 고리로 부르면."},{"s":"q:mk_hisu","t":"조사원이 버티지 못해요."},{"s":null,"t":"나는 탑으로 가겠다고 했다."}],"reward":{}},{"quest_id":"mkq_4","step":4,"title":"짐","goal":"명부 탑으로 간다","need":{"at":["myeongbu_tower"]},"lines":[{"s":null,"t":"마을 끝에서 작은 손이 내 소매를 붙잡았다."},{"s":"q:mk_daon","t":"혼자 가는 거 알아요. 저도 갈래요."},{"s":null,"t":"월하가 그 앞을 막아섰다."},{"s":"q:mk_wolha","t":"넌 여기 남아."},{"s":"q:mk_daon","t":"싫어요."},{"s":"q:mk_wolha","t":"네가 따라가 봐야 짐만 될 텐데."},{"s":"q:mk_daon","t":"아저씨는요? 아저씨도 따라갈 거잖아요."},{"s":null,"t":"월하는 대답하지 않았다."},{"s":"q:mk_daon","t":"그럼 저도 갈 거예요."},{"s":null,"t":"월하는 길게 한숨을 쉬고, 아이의 목덜미를 강아지 들듯 잡아 제 옆에 세웠다."},{"s":"q:mk_wolha","t":"혼자 두면 엉킴에 휘말려서 더 귀찮아질 테니까. 그것뿐이야. 내 옆에서 떨어지지 마, 꼬맹아."},{"s":null,"t":"다온은 월하를 흘겨보았지만, 손을 뿌리치지는 않았다."},{"s":null,"t":"탑 아래 뜰에서는 정청 사람들이 바닥에 먹줄을 치고 있었다. 아홉 칸. 희수가 그 가운데 서 있었다."},{"s":"q:mk_hisu","t":"조사원. 탑 안쪽 먹귀부터 정리해 주세요. 위로 올라갈수록 짙어요."}],"reward":{}},{"quest_id":"mkq_4","step":5,"title":"작성자 칸","goal":"명부 탑에서 먹귀를 5번 풀어 보낸다","need":{"at":["myeongbu_tower"],"tasks":[{"t":"win","r":["myeongbu_tower"],"n":5}]},"lines":[{"s":null,"t":"계단참에서 희수가 숨을 고르며 보고서 두 장을 내밀었다. 서율의 마지막 기록이었다."},{"s":null,"t":"구조한 사람들의 이름은 끝까지 또박또박했다. 그런데 작성자 칸의 「서율」은 장을 넘길수록 작아졌다. 흐려졌다. 마지막 장에서 작성자 칸은 비어 있었다."},{"s":"q:mk_hisu","t":"서율 조사원도 마지막까지 다른 사람들 이름을 불렀어요."},{"s":"q:mk_hisu","t":"정작 그분 이름을 부르는 사람은 없었지만요."},{"s":null,"t":"희수는 그 말을 하고 시선을 돌렸다. 아래 뜰에서 봉인진의 먹줄이 하나씩 완성되고 있었다."},{"s":null,"t":"한쪽 구석에서 월하가 흑련회 전서구에 쪽지를 매달고 있었다. 나는 그가 쓴 글을 우연히 보았다. 「빈 고리 대상. 침식 경미. 상품 가치 낮음. 추적 중단 요망.」"},{"s":null,"t":"손목을 지나 어깨까지 검게 물든 내 팔을 그도 알고 있었다. 월하는 내 눈길을 느끼고도 쪽지를 고치지 않았다. 전서구가 날아갔다."},{"s":"q:mk_wolha","t":"뭘 봐요. 위로 가요, 조사원."}],"reward":{"xp":4144}},{"quest_id":"mkq_4","step":6,"title":"회수 명부","goal":"명부 탑을 3번 탐색해 꼭대기로 오른다","need":{"at":["myeongbu_tower"],"tasks":[{"t":"search","r":["myeongbu_tower"],"n":3}]},"lines":[{"s":null,"t":"그동안, 탑 아래 뜰."},{"s":null,"t":"희수는 회수 명부를 펼쳤다. 봉인 대상자의 이름, 빈 고리에 쌓인 먹, 함께 거둘 기억 조각의 귀속. 칸마다 빈자리가 기다리고 있었다."},{"s":null,"t":"희수는 조사원의 이름을 적었다. 한 획, 또 한 획."},{"s":null,"t":"마지막 획 앞에서 붓이 멈췄다."},{"s":null,"t":"서율의 비어 있던 작성자 칸이 떠올랐다. 「서하」를 지우고 또 쓰던 아이의 손이 떠올랐다. 삐뚤빼뚤하던 글씨가 조금씩 반듯해지던 공책이 떠올랐다."},{"s":null,"t":"이 칸을 다 채우면, 그 사람이 붙든 것들까지 전부 지워진다."},{"s":null,"t":"평생 틀리지 않으려고 쓴 손이었다. 틀린 기록은 무효가 된다는 것을, 누구보다 잘 아는 손이었다."},{"s":null,"t":"희수는 마지막 획을 일부러 엇나가게 그었다."},{"s":null,"t":"붓을 내려놓았다. 손이 떨렸다. 다시 집지는 않았다."},{"s":"q:mk_hisu","t":"……이번에는, 남겨야겠어요."}],"reward":{"xp":4144}},{"quest_id":"mkq_4","step":7,"title":"먹귀","goal":"탑 꼭대기의 엉킨 먹귀 무리를 풀어 보낸다","need":{"at":["myeongbu_tower"],"tasks":[{"t":"win","m":["mk_tower_5"],"n":1}]},"lines":[{"s":null,"t":"마지막 무리가 몰려왔다. 나는 부르고, 또 불렀다. 먹귀가 흩어질 때마다 남은 기억이 몸 안으로 밀려들었다."},{"s":null,"t":"팔꿈치를 넘은 먹이 어깨를 덮었다. 목덜미가 차가웠다."},{"s":null,"t":"마지막 이름을 부른 순간이었다. 무엇이 끊어지는 소리는 없었다. 다만 나를 세상에 매달아 두던 끈이 거기 없었다."},{"s":null,"t":"발밑이 그대로인데 몸이 떠 있었다. 누군가 부르고 있었다. 어디서 오는 소리인지 알 수 없었다."},{"s":"q:mk_daon","t":"{이름} 님!"},{"s":null,"t":"그 말이 무슨 뜻인지 알 수 없었다."},{"s":"q:mk_meok","t":"나는 고개를 돌렸다."},{"s":"q:mk_meok","t":"나는 그 이름을 들었다. 내 것이 아니었다."},{"s":"q:mk_meok","t":"불러 줘. 기억해 줘. 잊지 마."},{"s":null,"t":"수많은 목소리가 한꺼번에 울었다. 나는 그 소리에 이끌려, 작은 아이에게 손을 뻗었다."}],"reward":{"xp":4144}},{"quest_id":"mkq_4","step":8,"title":"공책을 읽어","goal":"명부 탑 꼭대기에서 이어진다","need":{"at":["myeongbu_tower"]},"lines":[{"s":null,"t":"다온이 달려들었다. 월하가 먼저 아이의 팔을 붙잡았다."},{"s":"q:mk_daon","t":"놓으세요!"},{"s":"q:mk_wolha","t":"지금 네가 가 봐야 알아보지도 못해."},{"s":"q:mk_daon","t":"그래도 불러야 하잖아요!"},{"s":null,"t":"아이가 몸부림쳤다. 월하는 놓지 않았다. 그의 눈이 아이가 끌어안은 공책에 멎었다."},{"s":null,"t":"다온이 처음 내 이름을 따라 쓴 날부터 적어 온 이름들. 풀어 보낸 사람들. 「키가 큼」 같은 작은 글씨들."},{"s":null,"t":"월하는 처음으로, 아이에게 장난을 걸지 않았다."},{"s":"q:mk_wolha","t":"네 공책에 적힌 이름들, 아직 기억하지?"},{"s":null,"t":"다온이 눈물을 매단 채 고개를 끄덕였다."},{"s":"q:mk_wolha","t":"그럼 그걸 읽어. 처음부터. 네가 적은 이름 하나씩. 먹귀는 내가 막아."},{"s":null,"t":"월하가 엽전 끈을 풀어 휘둘렀다. 아이에게 다가오는 검은 형체를, 그는 몸으로 밀어냈다."},{"s":null,"t":"다온이 공책을 펼쳤다. 떨리는 목소리로, 첫 이름부터 읽기 시작했다."},{"s":null,"t":"월하가 내 손목을 붙잡았다. 아이에게 뻗은 손이었다."},{"s":"q:mk_wolha","t":"그만해요. 이제 그만 불러도 돼요."},{"s":"q:mk_wolha","t":"당신 이름부터 기억해요, 조사원."},{"s":null,"t":"그는 장부를 꺼내지 않았다. 값을 셈하는 눈이 아니었다."},{"s":null,"t":"그때 아래 뜰에서 빛이 올라왔다. 아홉 칸 봉인진이 닫히는 소리. 몸을 덮던 먹이 가라앉고, 끊어진 무엇이 다시 묶이기 시작했다."},{"s":null,"t":"그러나 매듭 안쪽에 쌓인 것들은, 아무도 가져가지 않았다."},{"s":null,"t":"나는 눈을 감았다."}],"reward":{"gil":460,"items":{"name_ink_charm":3,"register_slip":3}}},{"quest_id":"mkq_5","step":1,"title":"매듭 안쪽","goal":"아홉 칸 뜰에서 눈을 뜬다","need":{"at":["nine_court"]},"lines":[{"s":null,"t":"눈을 떴다. 뜰이었다. 그런데 뜰이 아니었다."},{"s":null,"t":"바닥이 아홉 칸으로 나뉜 명부였다. 가운데 칸에 내 이름이 적혀 있었다. 반쯤 지워진 채로."},{"s":null,"t":"나머지 칸마다 기억들이 흩어져 있었다. 처음 본 눈, 아궁이 냄새, 누군가의 약속. 내가 붙든 것들."},{"s":null,"t":"명부 저편에 먹그림자가 서 있었다. 그가 붓을 들었다. 한 칸이 지워졌다."},{"s":"q:mk_shadow","t":"나는 칸을 지웠다."},{"s":"q:mk_shadow","t":"나는 아프지 않았다."},{"s":null,"t":"봉인이 육신은 붙잡았다. 그러나 여기서 걸어 나가는 건, 나 혼자 해야 하는 일이었다."}],"reward":{}},{"quest_id":"mkq_5","step":2,"title":"같이 남아 다오","goal":"아홉 칸 명부에서 먹그림자와 싸운다","need":{"at":["nine_court"],"tasks":[{"t":"mj","n":1}]},"lines":[{"s":null,"t":"그림자의 붓이 느려졌다. 그가 지운 칸들 사이로 내가 되찾은 기억이 반짝였다."},{"s":"q:mk_shadow","t":"내려놓으면 아프지 않다."},{"s":"q:mk_shadow","t":"나는 이제, 하나도 아프지 않다."},{"s":null,"t":"그는 오래 말이 없었다. 먹으로 된 얼굴이 기울었다."},{"s":"q:mk_shadow","t":"……그래도, 같이 남아 다오."},{"s":"q:mk_shadow","t":"그러면 너는 나를 알 테니."},{"s":null,"t":"위로인지, 외로움인지. 그 목소리는 스스로도 모르는 것 같았다. 틀렸다고 말해 주기를 바라면서, 떠나지 말아 달라고 붙드는 목소리."},{"s":null,"t":"가운데 칸의 내 이름이 한 획, 더 흐려졌다."}],"reward":{"xp":17280}},{"quest_id":"mkq_5","step":3,"title":"돌아오는 이름","goal":"아홉 칸 뜰에서 이어진다","need":{"at":["nine_court"]},"lines":[{"s":null,"t":"그때 바깥에서 소리가 들렸다. 뜰 너머, 아주 멀리서."},{"s":null,"t":"처음은 정청의 사건 서기관 연서희였다. 다음은 반요촌의 여울, 단이. 언젠가 길에서 만난 사람들이 하나씩, 내 이름을 불렀다."},{"s":null,"t":"내가 기억하지 못하는 이름이었다. 그런데 그들은 기억하고 있었다. 내가 그들 곁에 남기고 온 이름을."},{"s":"q:mk_hisu","t":"{이름} 조사원."},{"s":null,"t":"처음이었다. 희수가 내 이름을 부른 건. 정확하고 또렷하게. 명부에 적듯이."},{"s":"q:mk_wolha","t":"……{이름}."},{"s":null,"t":"월하는 늘 하던 대로 가볍게 부르려다, 끝내 웃지 못했다. 목소리가 갈라졌다."},{"s":null,"t":"그리고 공책 넘기는 소리."},{"s":"q:mk_daon","t":"{이름} 님."},{"s":null,"t":"다온이 첫 장을 읽고 있었다. 획 하나가 빠진, 삐뚤빼뚤한 내 이름. 다음 장, 조금 반듯해진 이름. 팔 위에 써 준 이름. 마지막 장."},{"s":null,"t":"마지막 장의 이름은 반듯했다. 마지막 획을 끝까지 눌러 쓴 이름."},{"s":"q:mk_daon","t":"{이름} 님. 돌아와요. 제가 적어 놨어요. 안 지워져요."},{"s":null,"t":"아이의 목소리 뒤로, 먹귀들을 밀어내는 엽전 소리가 쉬지 않았다."}],"reward":{}},{"quest_id":"mkq_5","step":4,"title":"처음이자 마지막으로","goal":"아홉 칸 뜰에서 이어진다","need":{"at":["nine_court"]},"lines":[{"s":null,"t":"그 소리들이 가운데 칸을 붙잡고 있었다. 그런데 나는 아직, 그것이 내 이름이라는 걸 알지 못했다."},{"s":null,"t":"먹그림자가 붓을 내렸다."},{"s":null,"t":"그가 싸우는 동안 되찾은 기억들이 그의 안에서도 반짝이고 있었다. 동료의 보고서. 담장 너머의 아이. 「왜?」라고 대답하던 목소리."},{"s":null,"t":"그림자가 입을 열었다. 내 쪽을 보고."},{"s":"q:mk_shadow","t":"{이름}."},{"s":null,"t":"처음이자 마지막으로, 그가 나를 불렀다. 너는 나와 다른 길로 갈 수 있다고, 확인하듯이."},{"s":null,"t":"그 순간, 알았다."},{"s":null,"t":"나는 내 이름을 외쳤다."},{"s":null,"t":"가운데 칸의 글자가 검게, 또렷하게 돌아왔다."},{"s":null,"t":"그리고 나는 그를 보았다. 이름을 잃은 채 오래 서 있던 사람을."},{"s":null,"t":"나는 그의 이름을 불러 주었다."},{"s":null,"t":"「서율.」"},{"s":null,"t":"먹이 흘러내렸다. 그 아래, 사람의 얼굴이 있었다. 지쳐 있었고, 아주 오래 울다 그친 얼굴이었다."},{"s":"q:mk_seoyul","t":"……서하."},{"s":"q:mk_seoyul","t":"그 아이 이름이, 서하였지."},{"s":null,"t":"그는 돌아오지 못했다. 다만 흩어지는 마지막 순간만큼은, 먹그림자가 아니었다."},{"s":null,"t":"서율이라는 사람으로, 그는 흩어졌다."},{"s":null,"t":"눈을 뜨니 뜰이었다. 이번에는 정말 뜰이었다. 봉인진의 먹줄이 새벽빛에 옅어지고 있었다."},{"s":null,"t":"매듭 안쪽의 것들이 함께 풀려 나갔다. 누군가의 어머니 목소리, 처음 본 눈, 아궁이 냄새. 무엇이었는지 떠올리려 해도 떠오르지 않았다."},{"s":null,"t":"잃었다는 것만은 알았다."},{"s":null,"t":"손등을 보았다. 옅은 먹 자국 하나가 남아 있었다. 아이가 써 준 이름의 마지막 획 자리였다."},{"s":null,"t":"다온이 달려왔다. 이번에는 아무도 막지 않았다. 월하는 아이의 등을 떠밀고, 한 걸음 물러섰다."},{"s":null,"t":"아이는 내 손을 붙잡고 한참 울었다. 그러다 콧물을 훔치며 공책을 펼쳤다. 자기 이름을 손가락으로 짚고, 내 이름을 짚었다. 하나씩 확인하듯이."},{"s":"q:mk_daon","t":"다온. {이름} 님. ……맞죠?"},{"s":null,"t":"맞다고 했다. 아이는 또 울었다."},{"s":null,"t":"공책 뒷장에는 내가 풀어 보낸 이름들이 빼곡했다. 나는 더 이상 그들의 목소리를 모른다. 그래도 이름은 여기 있었다. 「키가 큼」 같은 작은 글씨와 함께."},{"s":null,"t":"희수는 정청 명부를 펼쳤다. 다온의 이름 옆, 거둘 차례를 적는 칸에 붓을 대려다 멈추고, 그 옆에 새 칸을 하나 그었다."},{"s":null,"t":"「불러 주는 이」."},{"s":null,"t":"그리고 그 칸에, 내 이름을 적었다. 이번에는 마지막 획까지 똑바로."},{"s":"q:mk_wolha","t":"이제야 쓸 만한 기록을 하나 만드셨네요, 서리님."},{"s":null,"t":"희수는 대꾸하지 않았다. 다만 월하를 쫓아내지도 않았다."},{"s":null,"t":"월하는 제 장부를 펼쳐, 한 장을 찢었다. 내 이름이 적혀 있던 장이었다. 그는 그걸 접어 품에 넣지도 않고, 바람에 날려 보냈다."},{"s":"q:mk_wolha","t":"값이 안 나가서요. 조사원은."},{"s":"q:mk_daon","t":"아저씨는 진짜 이름 언제 찾아요?"},{"s":null,"t":"월하는 대답하지 않고 엽전을 한 번 튕겼다. 떨어지는 엽전을 받아 쥐고 나서야 입을 열었다."},{"s":"q:mk_wolha","t":"……글쎄. 불러 줄 사람이 생기면?"},{"s":null,"t":"그 뒤로도 그는 이름을 사고팔았다. 다만 나에게는, 다시는 값을 부르지 않았다."},{"s":null,"t":"정청 서고. 내 기록은 서율의 기록 바로 옆 칸에 그대로 꽂혀 있었다. 다만 표지에 한 줄이 늘었다."},{"s":null,"t":"「돌아옴.」"},{"s":null,"t":"며칠 뒤, 다온은 빈칸 벌판의 사당에 갔다. 맨 끝 위패, 흐려진 「서하」를 먹으로 다시 덧썼다. 그 옆에 새 위패를 세우고, 한 글자씩 또박또박 적었다."},{"s":null,"t":"「서율」."},{"s":"q:mk_daon","t":"이제 둘이 같이 있어요."},{"s":null,"t":"한때 누군가의 이름을 붙들고 살았던 사람이, 이제 자기 이름으로 그 곁에 있었다."}],"reward":{"gil":470,"items":{"name_ink_charm":3,"drifting_name_thread":3}}}]$J$::jsonb) as x(quest_id text, step int, title text, goal text, need jsonb, lines jsonb, reward jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_patch_notes(note_id, title, body) values ('2.0.0', '2.0.0 · 묵적록', $N$귀허도 너머, 먹으로 지운 이름들이 모이는 땅 「묵적록」이 열립니다. 새 직업 「조련사」, 세력마다 새 지역 일곱 곳, 조사원의 모습을 꾸미는 「내 모습」도 함께 들어옵니다.

## 묵적록
### 최고 레벨 45
- 최고 레벨이 40에서 45로 오릅니다. 다음 레벨까지 드는 경험치 식은 그대로이고, 레벨마다 능력치 3점을 받습니다. 쌓아 둘 수 있는 능력치 포인트는 132점까지입니다.
- 장비 드롭은 Lv41부터 7단계 장비가 나옵니다.

### 새 지역 「묵적록」
- 귀허도 외전 「요인록」 다섯 장을 마치면 지도 왼쪽 위, 빙혼곡 너머에 묵적록이 나타납니다.
- 묵창 나루(안전지대 Lv40) · 빈칸 벌판 Lv41 · 먹비 숲 Lv42 · 명부 탑 Lv44 · 아홉 칸 뜰 Lv45. 지역마다 답사 길·채집터·요괴·원정지·조사 지점이 있습니다.
- 묵창 나루는 반요촌처럼 빈약한 안전지대입니다. 거래소·창고·마구간이 없고, 주막 상점은 사람마다 하루에 살 수 있는 개수가 정해져 있습니다. 되팔기와 판매 한도는 절반, 수리비는 세 배입니다.

### 이름 흐림
- 묵적록(나루 포함)에 있는 동안 늘 걸리는 약화입니다. 정신 손실 +15% · 받는 피해 +5% · 요괴 조우 +5%.
- 상태 칸 10칸에 세지 않고 상태판에 따로 보이며, 떠나면 바로 사라집니다.
- 이름 먹 부적(1시간)과 이름 새김 탕(2시간)으로 막을 수 있습니다.

### 명어와 미끼
- 낚시터가 여섯 곳 늘었습니다(바다 한 곳 포함). 한 지역에 낚시터가 둘이면 낚시 칸에서 고를 수 있습니다.
- 어종 열 가지가 늘었습니다. 수로·깊은 물·심연·늪·호수에 고루 더했고, 이미 있는 같은 물 낚시터에서도 나옵니다.
- 묵적록 낚시터마다 이름을 지킨 물고기 「명어」가 하나씩 삽니다. 정해진 시간대·날씨에 미끼(그 물에 사는 물고기 서너 종 가운데 아무것이나)를 걸어야 물고, 미끼는 던질 때마다 한 마리씩 씁니다.
- 명어와 명어로 만든 음식·가구·낚싯대는 거래할 수 없습니다.

### 재료·제작
- 묵적록 고유 재료 여덟 가지와 새 어종으로 만드는 재료가 생겼습니다.
- 7단계 장비 서른두 가지(장착 Lv42)와 7단계 생활 도구 열두 가지(채집도·곡괭이·낫·등·나침반·낚싯대 둘·제작 공구 다섯)를 묵창 나루에서 만들 수 있습니다.
- 소모품 셋(이름 먹 부적·먹귀 쫓는 향·먹비 우산), 새 어종 음식·약, 명어 음식 여섯 가지가 생겼습니다.
- 별채 가구 열세 가지가 늘었습니다. 그중 「명어 탁본 액자」 다섯(빈칸 가물치·먹비 대산천어·눈먼 용·죽간 대장어·먹비늘 다랑어 탁본)은 명어로 떠서 벽에 겁니다.

### 외전 「묵적록」
- 귀허도 외전 「요인록」을 마치면 본부 정청에서 다섯 장짜리 외전을 받을 수 있습니다(Lv40~45, 일지 › 주 이야기 › 묵적록).
- 정청 서리 희수, 나루의 아이 다온, 흑련회 거둠꾼 월하와 함께 이름이 흐려지는 나루의 일을 따라갑니다.

### 칭호·꾸미기
- 분류 「묵적록」 칭호 열두 가지(일부 숨김), 테두리 「먹비 테」, 낙관 「墨」, 이름 색 「먹빛 금」이 생겼습니다.
